/* ==========================================================
   accounting-lectures.js · 会计学（84 关）教材讲解章节
   ----------------------------------------------------------
   12 门课 ×（8 / 4）章，每章：导语 + 3 个知识要点 + 方法 + 易错点。
   依赖 lecture-apply.js 的 addLectures。
   ========================================================== */
addLectures('management-会计学', {
  '会计学原理': [
    ['会计基本概念', '本章解决会计为何存在、依据什么假设运行、提供什么样的信息才算有用三个基础问题，是全部后续核算方法的出发点。',
      ['会计以货币为主要计量单位，对特定主体的经济活动进行确认、计量、记录和报告，核算与监督是两大基本职能。', '四项基本假设：会计主体界定空间范围，持续经营假定不破产清算，会计分期划分期间，货币计量选定计量尺度。', '会计主体与法律主体不同，独资与合伙企业的会计主体是企业本身，法律主体未必都是会计主体。', '权责发生制以权利义务是否发生为标准，凡当期已实现的收入和已发生的费用，不论款项是否收付都计入当期。', '信息质量要求包括可靠性、相关性、可理解性、可比性、实质重于形式、重要性、谨慎性和及时性。', '谨慎性要求不高估资产或收益、不低估负债或费用，但不能成为设置秘密准备的理由。'],
      '拿到一笔业务先判断是否属于本会计主体的会计事项，再确认发生期间，按权责发生制归属，最后选择对应要素与科目。分析报表时用质量要求逐项检验，例如收入确认是否以控制权转移而非收款为依据。',
      '常见错误是把收付实现制套用到企业账上，以及把谨慎性理解为随意计提减值。纠正方法是牢记企业会计以权责发生制为确认基础，计提必须有客观证据并符合准则规定的条件。',
      ['会计假设不是抽象口号，而是核算规则的前提。会计主体解决了给谁记账，把股东个人消费排除在企业账外；持续经营使固定资产可以按历史成本分期折旧，而不必按清算价值计价；会计分期产生本期与非本期的划分，才有应收应付、待摊预提和期末结转；货币计量则要求以币值相对稳定为隐含条件，恶性通货膨胀下需改用一般物价水平会计。四项假设缺一，整套确认计量逻辑就无法成立。', '举例说明权责发生制：企业12月销售商品并交付，次年1月收款。按权责发生制，12月确认收入并结转成本，同时确认应收账款；按收付实现制则要到1月收款才确认。再如12月预付明年全年保险费，权责发生制下先记预付账款，再按月摊销计入费用。可见利润表反映价值创造过程，现金流量表反映现金流动过程，两者差异正是应计制造成的时间错配，也是分析利润含金量的切入点。']
    ],
    ['会计要素与等式', '本章回答会计用什么类别描述企业、这些类别之间保持什么恒等关系，以及任何一笔业务发生后等式为何仍然成立。',
      ['资产是过去交易或事项形成、由企业控制、预期会给企业带来经济利益的资源，三个条件缺一不可。', '负债是过去交易形成、预期导致经济利益流出企业的现时义务；所有者权益是资产扣除负债后的剩余权益。', '收入是日常活动形成、会导致所有者权益增加、与所有者投入资本无关的经济利益总流入；费用方向相反。', '静态等式为资产等于负债加所有者权益；扩展式为资产等于负债加所有者权益加收入减费用。', '业务对等式的影响共九种类型，可归纳为两边同增、两边同减、左边一增一减、右边一增一减。', '利得和损失分直接计入当期利润与直接计入所有者权益两类，后者如其他综合收益。'],
      '处理业务时先确定涉及哪些要素，再判断每个要素的增减方向，套入等式验证两边金额是否同时变动。编表前用扩展等式检查期末余额，把收入费用结转到本年利润后，扩展式应回归静态等式。',
      '最典型的错误是把预收货款确认为收入，或把赊购设备同时增加资产和费用。纠正方法是紧扣要素定义：预收款尚未转移控制权，属于合同负债；赊购设备应同时增加固定资产与应付账款，不影响费用。',
      ['九种业务类型可系统记忆。等式两边同增：赊购存货、取得借款；两边同减：用银行存款偿还借款；左边一增一减：以存款购入设备、收回应收账款；右边一增一减：将应付账款转为实收资本、提取盈余公积。任何业务都不会破坏等式，因为复式记账对每笔业务至少在两个账户等额记录，这正是等式恒成立的记账学基础。', '扩展等式把利润表与资产负债表连接起来。假设期初资产100万元、负债40万元、所有者权益60万元；本期收入50万元、费用30万元，若款项全部收付，则期末资产120万元、负债与权益合计也是120万元。若收入中有10万元未收款、费用中有5万元未付款，则资产为125万元、负债为45万元，权益仍为60万元加净利润20万元，等式依然成立。理解这一勾稽，才能解释净利润与现金流为何不同。']
    ],
    ['账户与复式记账', '本章解决经济业务如何转化为账簿记录，核心是账户结构、借贷方向与试算平衡，是编制会计分录的操作基础。',
      ['账户按经济内容分资产、负债、共同、所有者权益、成本、损益六类，按详细程度分总分类账与明细分类账。', '账户基本结构为左右两方，左方为借方、右方为贷方，哪方登记增加取决于账户性质。', '资产类、成本类账户借方记增加贷方记减少；负债类、所有者权益类、收入类账户方向相反。', '借贷记账法规则是有借必有贷、借贷必相等，可一借一贷、一借多贷、一贷多借，不允许多借多贷。', '试算平衡包括发生额平衡与余额平衡，依据是会计等式和借贷记账规则，只能发现部分错误。', '总账与明细账平行登记要求同依据、同期间、同方向、同金额。'],
      '编分录按三步走：先确定业务涉及的账户及其性质，再判断各账户金额的增减方向，最后按有借必有贷、借贷必相等的规则书写并检查金额。登账后月末结出各账户发生额与余额，编制试算平衡表验证借方合计等于贷方合计。',
      '常见错误是见到增加就记借方，或把费用增加记贷方。纠正方法是先判断账户性质再定方向，可借助口诀资产成本费用借增贷减、负债权益收入贷增借减，并用试算平衡与明细账核对双重验证。',
      ['试算平衡的局限必须清楚。漏记整笔业务、重记整笔业务、借贷方向同时记反、借贷金额同时错记相同数额、误用会计科目，这五类错误都不影响借贷合计相等，试算平衡表仍然平。因此试算平衡只是必要程序而非充分保证，还必须通过账证核对、账账核对、账实核对以及明细账与总账核对来发现错误。', '以赊购原材料为例：材料已验收入库、价款10万元、增值税进项1.3万元、款项未付。分录为借原材料10万元、借应交税费应交增值税进项税额1.3万元，贷应付账款11.3万元，借方合计等于贷方合计。若企业先支付定金2万元，则贷方拆为预付账款2万元与应付账款9.3万元，仍保持平衡。这说明分录的合法性来自业务实质，科目选择错误即使平衡也属错账。']
    ],
    ['主要经济业务核算', '本章把采购、生产、销售、期末结转串成完整业务链，训练按业务实质选择科目并编制连续分录的能力。',
      ['采购业务：材料验收入库按实际成本借记原材料，可抵扣增值税借记进项税额，未付款贷记应付账款。', '生产业务：直接材料、直接人工借记生产成本，车间一般耗费借记制造费用，月末分配转入生产成本。', '完工入库按完工产品成本借记库存商品、贷记生产成本；销售时确认收入并结转主营业务成本。', '销售业务确认收入贷记主营业务收入与应交税费销项税额，同时借记主营业务成本、贷记库存商品。', '期间费用中的管理费用、销售费用、财务费用不计入产品成本，直接计入当期损益。', '期末计提折旧、摊销、减值，结转收入费用至本年利润，最终形成未分配利润。'],
      '按业务发生顺序处理：取得并审核原始凭证，判断业务类型与金额构成，选择科目编制分录，过账后月末汇总。成本类账户先归集再分配，损益类账户月末必须结平，最后用试算平衡与报表勾稽检查整套账。',
      '最常见的是把增值税进项税额计入采购成本，或把车间设备折旧计入管理费用。纠正方法是牢记一般纳税人进项税可抵扣、不计成本；折旧按使用部门归属，生产设备折旧计入制造费用，管理部门才计入管理费用。',
      ['采购成本的确定要区分价、税、费。一般纳税人取得专用发票，买价与运输费计入存货成本，进项税额单独抵扣；小规模纳税人进项税不得抵扣，应计入成本。运输途中的合理损耗计入成本并提高单位成本，非正常损耗扣除赔偿后计入营业外支出或管理费用，不得计入存货成本。入库前挑选整理费计入成本，采购人员差旅费计入管理费用。', '生产成本的归集与分配是业务链的枢纽。假设本月领用材料20万元，其中产品用18万元、车间一般耗用2万元；生产工人工资8万元，车间管理人员工资2万元；制造费用共5万元，按生产工时分配，甲产品3000小时、乙产品2000小时。分配率为5万除以5000等于10元每小时，甲负担3万元、乙负担2万元。甲产品归集材料、人工与制造费用后转入库存商品，任何一环错配都会导致单位成本失真。']
    ],
    ['凭证账簿与核算形式', '本章讲凭证、账簿、报表三级加工线如何组织，重点掌握凭证审核、平行登记与三种核算形式的适用差异。',
      ['原始凭证证明业务发生，按来源分外来与自制；记账凭证依据审核无误的原始凭证编制，确定会计分录。', '记账凭证按用途分收款、付款、转账三类，按填制方式分复式与单式。', '凭证审核内容包括真实性、合法性、合理性、完整性、正确性，审核无误才能据以登账。', '账簿按用途分序时账、分类账、备查账；按外形分订本式、活页式、卡片式。', '平行登记要求总账与明细账依据相同、期间相同、方向相同、金额相等。', '记账凭证核算形式直接按凭证登总账；科目汇总表形式定期汇总；汇总记账凭证形式按对应关系汇总。'],
      '先审核原始凭证的真实合法完整，再编制记账凭证并复核借贷平衡，然后登记明细账与总账，月末对账、结账、编制报表。选择核算形式看单位规模与业务量：业务少用记账凭证形式，业务多用科目汇总表形式以减少登账工作量。',
      '常见错误是原始凭证未经审核即入账，或总账与明细账金额不一致却只改一方。纠正方法是建立凭证审核责任，错账按划线更正、红字冲销、补充登记三种方法处理，严禁涂改挖补，并坚持总账与明细账逐笔核对。',
      ['三种核算形式的差别在登记总账的依据。记账凭证核算形式直接依据每张记账凭证逐笔登记总账，程序简单、便于查对，但工作量随业务量线性增长，适合小型单位。科目汇总表核算形式定期把全部凭证按科目汇总，编制科目汇总表后一次登记总账，可试算平衡、减少工作量，但总账看不出业务对应关系。汇总记账凭证形式按收款、付款、转账分别汇总，保留对应关系，适合业务较多的大中型企业。', '错账更正必须区分情形。结账前发现记账凭证正确、登账时文字或数字笔误，采用划线更正法，在错误处划红线并由记账人盖章。记账凭证科目或金额错误且已登账，采用红字冲销法先冲原分录再编正确分录；若科目正确只是金额少记，采用补充登记法补记差额。已结账后发现错误，还需通过以前年度损益调整处理，不能直接改动上年账簿。']
    ],
    ['期末处理与报表', '本章解决期末账项调整、对账结账与三张报表编制，是把日常记录转化为对外报告的关键环节。',
      ['期末调整事项包括应计收入费用、递延收入费用、折旧摊销、资产减值与坏账计提。', '对账包括账证核对、账账核对、账实核对，账实不符需查明原因并编制调节表或报批处理。', '结账前应编制试算平衡表，结账后损益类账户无余额，资产、负债、权益类账户结出期末余额转入下期。', '资产负债表按资产等于负债加所有者权益编制，格式分账户式与报告式，项目按流动性排列。', '利润表按收入减费用等于利润编制，多步式依次列示营业利润、利润总额与净利润。', '现金流量表分经营、投资、筹资三类活动，正表用直接法，附注用间接法调节。'],
      '先做期末调整分录并过账，再结转损益、结出本年利润，随后编制试算平衡表，最后按勾稽关系编表。编表后检查资产负债表未分配利润变动是否等于净利润减利润分配，货币资金期末余额是否与现金流量表一致。',
      '常见错误是结转损益后仍保留收入费用余额，或报表不平就随意改动数字。纠正方法是明确损益类账户结账后必须为零，报表不平应先查试算平衡、漏记业务、科目用错和结转遗漏，逐项核对而非硬凑差额。',
      ['报表勾稽关系是自检的核心工具。资产负债表期末未分配利润等于期初未分配利润加本期净利润减提取盈余公积减分配股利；资产总计等于负债和所有者权益总计；现金流量表期末现金及现金等价物余额应等于资产负债表货币资金中可列入现金等价物的部分。任何一条不成立，说明调整、结转或编表环节存在遗漏。', '以折旧与摊销说明调整的必要性。设备原值60万元、预计使用5年、无残值，年限平均法下月折旧1万元，生产用设备分录为借制造费用1万元、贷累计折旧1万元；管理部门使用则借管理费用。无形资产摊销借管理费用或制造费用、贷累计摊销。调整分录不改变现金，但改变费用与资产账面价值，因此净利润下降而经营现金流不变，这正是间接法调节的起点。']
    ],
    ['报表分析基础', '本章解决如何从三张报表读出偿债、盈利与现金质量，并用杜邦体系把比率拆解为可解释的驱动因素。',
      ['偿债能力：流动比率等于流动资产除以流动负债，速动比率剔除存货，资产负债率等于负债除以资产。', '营运能力：应收账款周转率等于营业收入除以平均应收账款，存货周转率等于营业成本除以平均存货。', '盈利能力：毛利率、净利率、总资产净利率、净资产收益率，分母优先使用平均余额。', '杜邦分析：净资产收益率等于净利率乘总资产周转率乘权益乘数，对应盈利、营运、杠杆三个维度。', '现金流质量：经营现金流净额除以净利润长期低于1，说明利润多沉淀在应收与存货。', '比率分析受会计政策、行业差异与期末时点影响，需结合趋势、同业与附注阅读。'],
      '先做三年趋势与结构分析看变化方向，再算比率并与同业均值比较，然后用杜邦体系分解净资产收益率变动来源，最后回到附注验证异常项目，如应收激增、存货跌价准备计提不足。',
      '常见错误是认为流动比率越高越好、净利润等于现金流。纠正方法是结合行业与资产结构判断流动性，流动比率过高可能意味着存货积压或资金闲置；同时用经营现金流与净利润比值检验利润含金量。',
      ['杜邦分解的实战价值在于定位。假设净资产收益率从15%降到10%，若净利率从8%降到5%、周转率与权益乘数不变，问题在成本或价格；若净利率稳定而总资产周转率从1.2降到0.8，问题在资产扩张低效或收入下滑；若权益乘数上升而收益率仅微增，说明增长靠加杠杆，风险在累积。分解后必须回到业务解释，而不是停在数字。', '利润含金量分析可用三个指标。一是经营现金流净额与净利润之比，持续小于1需警惕；二是应收账款增速与收入增速比较，应收远快于收入说明放宽信用或存在虚增；三是存货周转天数变化，若收入增长而存货更快增长，可能存在滞销。以某企业净利润5000万元、经营现金流1000万元、应收增加6000万元为例，利润主要被应收占用，需核查收入确认政策与回款能力。']
    ],
    ['会计实训', '本章以完整账套检验前七章知识能否落地，重点在建账、凭证、登账、结账、编表五个环节的闭环操作。',
      ['建账包括确定会计政策、设置科目表、录入期初余额并试算平衡，是整套账的起点。', '日常核算按业务发生顺序填制审核凭证、登记明细账，做到日清月结。', '期末完成折旧摊销、税费计提、成本结转、损益结转，并编制调整后试算平衡表。', '对账结账后编制资产负债表、利润表、现金流量表，并核对勾稽关系。', '电算化环境需完成账套初始化、科目与辅助核算设置、期初导入、月末结账与反结账控制。', '档案管理要求凭证装订、账簿打印归档、报表签章，保管期限符合会计档案管理办法。'],
      '按建账、日常、期末、报表四阶段推进，每阶段留工作底稿；用试算平衡表、明细账与总账核对、三表勾稽三道关卡自检。遇到不平先定位到具体科目与凭证，再逐笔追溯，不要直接改报表。',
      '常见问题是科目设置过粗导致明细无法核对、期初余额未试算平衡就开账、月末忘记结转成本。纠正方法是建账时先跑通期初平衡，按业务需要设置明细与辅助核算，并建立月末结账清单逐项打勾。',
      ['实训常见业务应覆盖：收到投资款、购入设备与材料、支付货款、领用材料、计提工资与社保、支付水电费、完工入库、销售确认收入并结转成本、计提折旧与坏账、计算增值税与附加税、结转损益、提取盈余公积、分配股利。每类业务至少练一遍完整凭证链，才能真正掌握科目对应关系。', '电算化实训的关键控制点：一是期初余额必须与手工账或上年末报表一致并试算平衡；二是凭证审核与记账岗位分离，已记账凭证不能随意修改；三是月末结账前检查是否存在未记账凭证、未结转损益；四是反结账需授权并留痕。忽视这些控制，系统虽能出表，数据可靠性却无法保证。']
    ]
  ],

  '微观经济学': [
    ['供求与弹性', '本章建立价格由供求共同决定的框架，并用弹性把价格变动与数量、收益、税负归属联系起来。',
      ['需求定律指其他条件不变时价格上升需求量下降，供给定律相反；价格变动表现为沿曲线移动。', '需求曲线平移源于收入、偏好、相关品价格、预期与买者数量；供给平移源于成本、技术、预期与卖者数量。', '均衡价格使需求量等于供给量；供过于求价格下降，供不应求价格上升。', '需求价格弹性等于需求量变动百分比除以价格变动百分比，中点法可避免基准差异。', '弹性大于1为富有弹性，降价增加总收入；小于1为缺乏弹性，提价增加总收入；等于1收入不变。', '收入弹性大于0为正常品、小于0为低档品；交叉弹性大于0为替代品、小于0为互补品。'],
      '先画供求图判断是沿曲线移动还是曲线平移，再求新均衡；涉及收益变化时先算弹性大小，涉及税负时比较供求弹性，弹性小的一方承担更多税负。',
      '常把需求增加与需求量增加混用，或认为曲线越陡弹性越大。纠正方法是区分平移与沿曲线移动，并牢记弹性是百分比之比，斜率相同而位置不同时弹性也不同。',
      ['弹性与总收入的关系可用简单推导说明。总收入等于价格乘数量，价格上升时价格增、数量减，若需求缺乏弹性，数量下降幅度小于价格上升幅度，总收入增加；若富有弹性则相反。因此农产品缺乏弹性，丰收反而可能谷贱伤农；奢侈品富有弹性，降价促销常能扩大收入。企业定价必须先估计弹性区间。', '税收归宿由供求弹性决定。对卖方征税使供给曲线上移，均衡价格上升、数量下降；若需求缺乏弹性而供给富有弹性，价格上升接近税额，消费者承担大部分税负；若需求富有弹性，卖方承担更多。无论法律上向谁征税，经济归宿相同。这一结论是分析消费税、社保缴费与最低工资影响的基础。']
    ],
    ['消费者行为', '本章解释消费者如何在有限收入下选择商品组合，核心工具是效用、预算线与无差异曲线。',
      ['总效用是消费商品获得的满足总和，边际效用是增加一单位带来的效用增量，边际效用递减。', '预算线表示收入与价格给定时可购买的商品组合，斜率为两商品价格之比的负值。', '无差异曲线表示带来相同效用的组合，凸向原点，斜率绝对值为边际替代率。', '消费者均衡条件为两商品边际效用除以价格相等，即每单位货币的边际效用相等，预算线与无差异曲线相切。', '价格变动的总效应分解为替代效应与收入效应；正常品两者同向，低档品收入效应反向，吉芬品总效应反向。', '消费者剩余是愿意支付与实际支付之差，用需求曲线以下价格线以上面积衡量。'],
      '先写预算约束，再列效用函数求边际效用，令单位货币边际效用相等求最优数量，最后用预算线检验是否花完收入；分析价格变化时分别画出替代效应与收入效应。',
      '常见错误是认为边际效用递减意味着总效用下降，或把低档品等同于吉芬品。纠正方法是明确边际量为正时总效用仍上升，吉芬品要求收入效应足够大且为负，属低档品的特例。',
      ['用数字说明均衡。设收入120元，x价格2元、y价格3元，边际效用分别为80减2x与90减3y。均衡需两者除以价格相等，即(80减2x)除以2等于(90减3y)除以3，整理得x减y等于10。代入预算2x加3y等于120得y等于20、x等于30。此时每元边际效用均为10，预算恰好用完。', '替代效应与收入效应的区分是理解需求曲线斜率的关键。价格下降时，消费者倾向于多买变便宜的商品，这是替代效应；同时实际购买力提高，正常品会多买，低档品可能少买。正常品两种效应同向，需求曲线必然向右下；低档品若替代效应大于收入效应，需求曲线仍向右下；只有收入效应反向且超过替代效应，才形成吉芬品，现实中极为罕见。']
    ],
    ['生产与成本', '本章从生产函数推导成本曲线，解释短期边际报酬递减与长期规模经济如何决定企业供给行为。',
      ['短期生产中总产量、平均产量与边际产量关系为边际产量穿过平均产量最高点，边际产量为零时总产量最大。', '边际报酬递减规律源于固定要素不变而可变要素不断增加，是短期成本曲线呈U形的原因。', '短期总成本等于固定成本加可变成本，平均成本等于总成本除以产量，边际成本为总成本增量。', '边际成本穿过平均可变成本与平均成本的最低点，固定成本只影响平均成本不影响边际成本。', '长期平均成本下降为规模经济，上升为规模不经济，长期成本曲线是短期成本曲线的包络线。', '短期停产看价格是否覆盖平均可变成本，长期退出看价格是否覆盖平均总成本。'],
      '决策先判断时间维度，短期固定成本沉没，只比较价格与平均可变成本；长期全部成本可调整，比较价格与平均成本。求最优产量令边际成本等于边际收益，再检验是否高于停业点。',
      '常把固定成本计入停产决策，或认为平均成本最低点就是利润最大点。纠正方法是短期停产只看平均可变成本，利润最大由边际成本等于边际收益决定，平均成本最低仅表示单位成本最优。',
      ['成本曲线关系可推导。边际成本是总成本的斜率，平均成本是总成本与原点连线的斜率。当边际成本低于平均成本时，平均成本被拉低；高于时被拉高；因此边际成本必在平均成本最低点相交。平均可变成本同理。固定成本只影响平均成本，不影响边际成本与平均可变成本。这解释了为什么亏损企业只要价格高于平均可变成本仍应继续生产，因为可以弥补部分固定成本。', '举例：某厂固定成本100万元，产量1万件时平均可变成本60元、价格70元。此时价格高于平均可变成本，每件贡献10元，可弥补固定成本10万元，短期应继续生产；若价格降到50元，低于平均可变成本，每多生产一件多亏10元，应立即停产。长期若价格持续低于平均总成本，企业应退出。决策的核心是增量而非账面利润。']
    ],
    ['市场结构', '本章按厂商数量、产品差异与进入壁垒划分四类市场，比较其定价、产量与效率差异。',
      ['完全竞争厂商是价格接受者，需求曲线水平，短期边际收益等于价格，长期经济利润为零且价格等于平均成本最低点。', '垄断厂商面临向下倾斜需求曲线，边际收益低于价格，按边际收益等于边际成本定产量再按需求曲线定价。', '垄断产量低于社会最优，价格高于边际成本，形成无谓损失，还可能产生寻租与管制难题。', '垄断竞争产品有差异、进出自由，短期可有经济利润，长期利润趋于零但价格仍高于边际成本。', '寡头厂商相互依存，用古诺模型、价格领导与博弈论分析，可能出现合谋与囚徒困境。', '价格歧视分一级、二级、三级，实施条件是市场可分割、需求弹性不同、能防止转售。'],
      '先按厂商数量、产品差异、进入壁垒判断市场类型，再写出收益函数与成本函数，令边际收益等于边际成本求产量，最后比较价格与边际成本判断效率损失。',
      '常见错误是认为垄断者可以任意定价，或认为垄断竞争长期零利润等于完全竞争。纠正方法是垄断者受需求曲线约束，价格由产量与需求共同决定；垄断竞争长期价格仍高于边际成本，存在多样性带来的效率代价。',
      ['完全竞争长期均衡条件为价格等于边际收益等于边际成本等于平均成本最低点，经济利润为零，消费者剩余与生产者剩余之和最大。垄断厂商均衡为边际收益等于边际成本，此时价格大于边际成本，产量低于竞争水平，形成无谓损失三角形。若政府按价格等于边际成本管制，厂商可能亏损需补贴；按价格等于平均成本管制可实现盈亏平衡但仍有低效，这体现管制在效率与可持续之间的权衡。', '价格歧视的福利含义不同。一级歧视按每个消费者的保留价格收费，产量达到竞争水平但全部剩余归厂商；二级歧视按购买量分段定价，如阶梯电价；三级歧视按群体分市场定价，如学生票。三级歧视要求两个市场弹性不同且不能转售，弹性小的市场定价高。分析时先判断能否分割与阻止套利，再比较各市场边际收益等于边际成本。']
    ],
    ['要素市场', '本章说明工资、地租与利息如何由要素供求决定，核心是派生需求与边际收益产品。',
      ['要素需求是派生需求，取决于产品需求、要素生产率与产品价格。', '完全竞争厂商雇佣原则为边际收益产品等于边际要素成本，边际收益产品等于边际收益乘边际产量。', '产品市场完全竞争时边际收益产品等于价格乘边际产量，即边际产品价值。', '劳动供给曲线先向右上后可能向后弯曲，替代效应与收入效应方向相反。', '买方垄断下厂商面临向上倾斜的要素供给曲线，边际要素成本高于工资，雇佣量低于竞争水平。', '地租由土地固定供给决定，经济租是要素收入超过机会成本的部分，利息由资本供求决定。'],
      '先判断产品市场与要素市场结构，再算边际收益产品并与要素价格比较决定雇佣量；分析政策时先看市场结构，再判断最低工资或工会谈判对工资与就业的影响。',
      '常把要素价格等于边际产品价值简单套用于所有市场，或认为最低工资必然减少就业。纠正方法是产品市场不完全竞争时边际收益产品小于价格乘边际产量；买方垄断下最低工资可能同时提高工资与就业。',
      ['最低工资的效应取决于市场结构。完全竞争劳动市场中，最低工资高于均衡工资会减少雇佣量，形成失业；买方垄断市场中，厂商原本按边际收益产品等于边际要素成本压低工资与雇佣量，设定略高的最低工资可使工资接近竞争水平，反而增加就业。现实还受覆盖范围、执法力度与劳动需求弹性影响，不能一概而论。', '人力资本投资可用净现值判断。设读研两年，每年直接成本3万元、放弃工资8万元，毕业后每年多收入4万元、工作30年，折现率5%。总成本22万元，收益年金现值约为4乘15.37等于61.5万元，净现值为正，投资合理。若折现率提高或收益年限缩短，结论可能反转。这说明教育决策同样遵循边际收益与成本比较。']
    ],
    ['市场失灵', '本章分析价格机制无法实现帕累托最优的情形，并比较政府干预与产权界定的适用条件。',
      ['负外部性使社会边际成本高于私人边际成本，产出过多；正外部性使社会收益高于私人收益，产出不足。', '庇古税按外部成本征税使外部成本内部化；补贴用于正外部性；排污权交易以总量控制实现成本最小化。', '科斯定理表明交易成本为零且产权明晰时，无论初始产权归谁，市场谈判都能达到有效率结果。', '公共品具有非排他性与非竞争性，市场供给不足，需政府提供或公共选择机制。', '信息不对称导致逆向选择与道德风险，可用信号、筛选、担保与激励合同缓解。', '垄断、公共资源过度使用与协调失败也属市场失灵，需反垄断、产权界定与集体行动。'],
      '先判断失灵类型是外部性、公共品、信息不对称还是垄断，再选工具：外部性用税补或产权，公共品用政府提供，信息问题用信号与合同，垄断用反垄断与管制。',
      '常把公共品与公共资源混淆，或认为政府干预一定优于市场。纠正方法是公共品非排他且非竞争，公共资源非排他但竞争；干预需比较政府失灵与市场失灵的成本。',
      ['外部性与产权界定的关系可用污染案例说明。河流上游工厂排污影响下游渔民，若产权归渔民，工厂需赔偿或安装治污设备；若产权归工厂，渔民可付费请工厂减排。在交易成本为零且双方人数少时，无论产权归谁，最终排污量都达到社会最优，差别只在收入分配。现实中交易成本高、人数多，才需要庇古税或排污权交易。', '信息不对称的两种表现不同。逆向选择发生在交易前，买方无法识别质量，劣质品驱逐优质品，二手车市场是典型；解决办法是信号，如质保、品牌、学历。道德风险发生在交易后，一方行为不可观察而改变激励，如投保后疏于防范；解决办法是免赔额、共保与绩效合同。分析题目先判断发生在签约前还是签约后。']
    ],
    ['博弈与信息', '本章研究决策相互依赖时的策略选择，用纳什均衡刻画稳定结果，并解释合作为何难以自发实现。',
      ['博弈三要素为参与人、策略集与收益函数；按时间分静态与动态，按信息分完全与不完全信息。', '占优策略是对手任何策略下都最优的策略；纳什均衡是给定对手策略无人愿意单独偏离的组合。', '囚徒困境中个体理性导致集体非最优，反映合作与承诺问题。', '重复博弈中触发策略、声誉与惩罚机制可支持合作，贴现因子越高合作越稳定。', '混合策略均衡按概率随机选择，概率由使对手在纯策略间无差异的条件计算。', '信号是信息优势方主动传递，筛选是信息劣势方设置条件甄别，二者都要求成本差异。'],
      '先写收益矩阵，对每个对手策略找本方最优反应，划线求交点得到纳什均衡；动态博弈用逆向归纳，信息不对称先判断信号与筛选方向。',
      '常把纳什均衡等同于帕累托最优，或认为混合策略是随意选择。纠正方法是纳什均衡只保证稳定性不保证效率，混合策略的概率由使对手无差异的条件计算得出。',
      ['以囚徒困境说明。两人均沉默各判1年，一方坦白另一方沉默则坦白者释放、沉默者10年，均坦白各判5年。给定对方沉默，坦白更好；给定对方坦白，坦白仍更好，故均坦白是占优策略均衡，但结果劣于均沉默。这说明缺乏可执行承诺时，个体理性会侵蚀共同利益。', '重复博弈可改变结果。若双方采用触发策略：一直合作，一旦对方背叛则永久回到不合作，在无限重复且贴现因子足够高时，合作路径的长期收益超过一次性背叛收益，合作成为均衡。贴现因子接近1表示耐心，合作越容易维持；若博弈次数有限且已知，逆向归纳会使合作在最后一期瓦解。']
    ],
    ['微观应用', '本章把供求、弹性、剩余与外部性用于政策评估，训练从图形均衡走向福利结论的分析路径。',
      ['消费者剩余是需求曲线以下价格以上面积，生产者剩余是价格以下供给曲线以上面积。', '竞争均衡使总剩余最大；价格上限造成短缺，价格下限造成过剩，两者都产生无谓损失。', '税收使买卖价格分离，无谓损失与弹性、税率平方相关，拉弗曲线描述税收与收入关系。', '补贴增加交易量但成本可能超过剩余增加，需比较效率与分配目标。', '政策评估应区分短期与长期、局部均衡与一般均衡，并考虑行政成本与扭曲。', '成本收益分析用现值比较政策收益与成本，敏感性分析检验结论稳健性。'],
      '三步走：识别市场与主体，画图判断政策使哪条曲线移动或形成楔子，再比较新均衡下的价格、数量与剩余变化，最后讨论分配效应与长期调整。',
      '常见错误是只看价格变化不看数量与剩余，或把税收全部视为无谓损失。纠正方法是明确税收同时产生收入与效率损失，分析时分别计算消费者剩余、生产者剩余、税收收入与无谓损失四块。',
      ['价格上限的福利分析：设定低于均衡的价格，供给量减少、需求量增加，实际交易量由供给决定，形成短缺。消费者剩余一部分转移给仍能买到的消费者，一部分因买不到而损失；生产者剩余减少；总剩余下降形成无谓损失。若排队、配给与黑市出现，隐性成本进一步扩大，因此房租管制长期常导致供给质量下降。', '税收归宿与无谓损失可同时分析。对卖方从量征税，供给曲线上移，均衡数量下降。税负分担由弹性决定，需求弹性小则消费者承担多。无谓损失近似为二分之一乘税额乘数量减少量，税率提高使数量扭曲加剧，损失按税率平方增长。因此高税率不一定带来高税收，超过临界点后税收收入反而下降，这就是拉弗曲线的含义。']
    ]
  ],

  '管理学原理': [
    ['管理与管理者', '本章界定管理的内涵与管理者角色，明确四大职能与三类技能，为后续各职能的学习提供框架。',
      ['管理是在特定组织中通过计划、组织、领导、控制协调他人活动，以有效实现目标的过程。', '效率关注投入产出比，效果关注目标达成度；管理要兼顾两者，先做对的事再把事做对。', '四大职能：计划确定目标与路径，组织配置资源与权责，领导激励与沟通，控制衡量与纠偏。', '明茨伯格十种角色归为人际角色、信息角色、决策角色三类，随层级与情境变化。', '卡茨三类技能为技术技能、人际技能、概念技能；基层重技术，高层重概念。', '管理者面临角色冲突、时间碎片化与责任压力，需做好优先级管理与授权。'],
      '遇到管理问题先定位属于哪个职能，再判断是效率问题还是效果问题，最后选择工具；分析管理者行为时用角色理论与技能结构解释其关注重点。',
      '常把管理等同于自己完成任务，或把效率与效果混为一谈。纠正方法是明确管理的产出是他人与团队的结果，效率高不等于方向对，效果好在低效率下也难以持续。',
      ['不同层级的管理者时间分配不同。高层把更多时间用于计划与外部关系，基层更多用于现场指挥与控制；中层承上启下，既要把战略翻译为部门目标，又要协调跨部门资源。现实中管理者常被会议与突发事件切碎时间，德鲁克建议记录时间、集中整块时间处理重要事项，并学会授权。', '角色理论可用一个场景说明。部门经理上午参加公司战略会，扮演信息接收者与决策者；中午与下属谈话，扮演领导者与激励者；下午接待客户，扮演联络者与谈判者；晚上审阅报表，扮演监控者。同一人一天内切换多种角色，若角色认知不清，容易出现越位或缺失，例如只顾对外应酬而忽视内部辅导。']
    ],
    ['管理思想演进', '本章梳理管理思想从经验到科学、从效率到人性的演进，帮助识别企业做法背后的理论假设。',
      ['泰勒科学管理以时间研究、动作研究、标准化与差别计件工资提高效率，主张劳资合作。', '法约尔提出计划、组织、指挥、协调、控制五职能与十四项管理原则，强调管理教育。', '韦伯官僚制强调层级、规则、非人格化与专业化，是大组织稳定运行的基础。', '霍桑实验发现社会与心理因素影响产出，开启人际关系学派与行为科学。', '系统理论把组织视为开放系统，权变理论强调管理方式随环境与任务变化。', '现代管理思潮包括全面质量管理、流程再造、学习型组织、精益与敏捷。'],
      '分析企业做法时先判断其人性假设是经济人、社会人还是自我实现人，再对应激励与控制方式；评价管理工具时结合环境不确定性、规模与任务特征。',
      '常把霍桑实验结论简化为照明越亮效率越高，或认为科学管理已完全过时。纠正方法是霍桑实验的核心是社会因素与非正式组织，科学管理的标准化与工时研究仍是现代精益管理的基础。',
      ['科学管理的具体贡献包括：用秒表与动作分析确定标准工时，实行差别计件工资，分离计划与执行，设立职能工长。它把经验管理变为可测量、可复制的体系，但也把工人视为经济人，忽视心理需求，导致劳资对立。今天的外卖配送算法、流水线节拍设计仍能看到其影子，争议也相似。', '权变理论的核心命题是没有唯一最佳管理方式。同一领导风格在高度结构化任务与低成熟度下属中有效，在高专业自主团队中可能失效；同一组织结构在稳定环境中高效，在快速变化环境中显得僵化。因此分析案例必须先识别环境不确定性、技术复杂性与人员特征，再判断管理方式的匹配度。']
    ],
    ['计划与决策', '本章解决目标如何转化为可执行计划，以及在不同条件下如何系统比较方案。',
      ['计划层次由高到低为使命、战略、战术、作业计划，时间跨度与具体程度逐级变化。', '目标设定遵循SMART原则：具体、可衡量、可实现、相关、有时限。', '计划步骤包括估量机会、设定目标、确定前提、拟订方案、评价方案、选择方案、编制派生计划与预算。', '决策步骤为识别问题、确定标准、分配权重、拟定方案、评估方案、选择、实施与反馈。', '不确定决策准则有乐观、悲观、折中、等可能、最小后悔值，选择取决于决策者风险偏好。', '群体决策可提高信息量与接受度，但存在从众、群体极化与责任分散。'],
      '先明确目标与约束，再把方案列成决策矩阵，按标准打分或计算期望值，最后做敏感性分析；实施后设置里程碑与反馈节点，避免计划一次性锁死。',
      '常见错误是目标写成口号无法衡量，或决策时把沉没成本计入。纠正方法是用SMART逐项检验目标，决策只看未来增量收益与成本，已发生且无法收回的支出不影响选择。',
      ['决策矩阵可用简单例子说明。某企业要在三个方案中选择，标准为投资回报、风险、实施难度，权重分别为0.5、0.3、0.2，三方案加权得分分别为7.8、8.1、6.9，则选第二方案。若权重变化，结论可能反转，因此要说明权重依据并做敏感性分析。群体打分时可用德尔菲法减少权威影响。', '计划与弹性的平衡体现在滚动计划与情景规划。滚动计划按月或季修订，近期详细远期粗略；情景规划设定乐观、基准、悲观三种情景，为每种情景准备触发条件与应对方案。这样既不因频繁变化放弃计划，也不因固守年度预算而错失调整时机。预算松弛是常见问题，需用零基预算与对标加以约束。']
    ],
    ['组织', '本章解决分工、部门化、层级与授权如何组合成有效结构，核心是让权责与战略、环境相匹配。',
      ['组织设计六要素为工作专业化、部门化、指挥链、管理幅度、集权与分权、正规化。', '部门化方式有职能、产品、地区、流程、客户；矩阵制同时按职能与项目双重汇报。', '管理幅度与管理层次成反比，幅度受任务相似性、下属能力、地理分布影响。', '常见结构有直线制、直线职能制、事业部制、矩阵制、网络型与平台型。', '授权要授责任、授权力、授利益并保留最终责任，避免反向授权与越权。', '组织变革阻力来自利益、习惯、认知与结构惯性，需配套沟通、培训与激励。'],
      '先看战略与业务复杂度，再看环境不确定性与规模，选择结构；设计部门时画清汇报线、职责边界与接口，最后用决策速度与协作成本检验方案。',
      '常认为扁平化就是取消管理层，或认为矩阵制一定优于职能制。纠正方法是扁平化是减少层级而非取消管理，矩阵制增加协作也带来双重指挥冲突，需明确主责与考核归属。',
      ['事业部制与职能制的差异在责任中心。事业部按产品、地区划分，拥有较完整经营权限，独立核算利润，适合多元化、市场差异大的企业，但可能重复配置资源、削弱规模效应。职能制按专业分工，效率高、专业深，但跨部门协作难、响应慢。选择时可考虑业务相关性、总部能力与信息系统成熟度。', '管理幅度可用实例估算。若一线员工64人，管理幅度为8，则需8名基层主管、1名中层，共3层；若幅度为4，则需16名主管、4名中层、1名高层，共4层。幅度缩小增加层级与沟通成本，幅度扩大对下属能力与标准化要求更高。因此幅度不是越大越好，要与任务标准化程度和信息系统支持匹配。']
    ],
    ['领导与激励', '本章区分领导与管理的差异，比较领导理论与激励理论，解决如何让人愿意追随并持续投入。',
      ['领导是影响他人自愿追随以实现目标的过程，权力来源包括法定、奖赏、强制、专家与参照。', '领导理论经历特质论、行为论到权变论，费德勒模型按关系、任务结构与职位权力判断情境。', '情境领导按下属成熟度分指导、教练、支持、授权四种风格，成熟度提高逐步放权。', '需求层次理论由生理、安全、社交、尊重到自我实现，双因素理论区分保健因素与激励因素。', '期望理论认为激励力等于效价乘期望乘工具性，公平理论关注投入产出比与参照对象比较。', '强化理论通过正强化、负强化、惩罚与忽视塑造行为，反馈要及时且具体。'],
      '先诊断任务结构与下属成熟度，再选领导风格；设计激励时同时检查保健因素是否满足、目标是否可达、回报是否公平，最后用绩效与反馈闭环验证。',
      '常认为高薪等于高激励，或认为保健因素可以产生满意。纠正方法是保健因素只能消除不满，激励需来自成就、认可与成长；薪酬要结合公平感与期望值，而非单纯提高数额。',
      ['双因素理论常被误解。公司政策、监督、工作条件、薪酬属于保健因素，改善它们只能把不满意变为没有不满意，不能产生满意；成就、认可、责任、成长属于激励因素，具备才能产生满意。因此加薪短期有效，长期若无成长与认可，员工仍会离职。实践中要把薪酬与绩效、发展通道结合。', '期望理论可用于解释激励失效。若员工认为目标太难，期望值低；若认为完成目标也不会得到奖励，工具性低；若奖励不是自己看重的，效价低。三者任一接近零，激励力都接近零。管理者应设定可达成的目标、明确兑现承诺、提供个性化奖励，并定期反馈进度。']
    ],
    ['控制与沟通', '本章解决如何确保行动不偏离计划，以及信息在组织中如何不失真地传递与反馈。',
      ['控制过程四步为确立标准、衡量实际绩效、比较偏差、采取纠偏行动。', '控制类型分前馈控制、同期控制、反馈控制，分别针对输入、过程与产出。', '有效控制遵循关键点原则、例外原则、及时性与经济性，避免过度控制与目标置换。', '偏差可能来自行动偏离标准，也可能标准本身不合理，纠偏要先判断原因。', '沟通分正式与非正式、上行下行平行；障碍包括过滤、选择性知觉、情绪、语言与信息过载。', '有效沟通要明确目的、选择渠道、积极倾听、确认理解并建立反馈机制。'],
      '先设定可衡量标准，再设计数据采集频率与责任人，发现偏差后区分偶发与系统原因，最后决定调整行动或修订标准。沟通前先明确受众与目的，重要信息用多渠道并复述确认。',
      '常把控制理解为越严越好，或只做事后反馈。纠正方法是控制要抓关键少数、及时前移，过度控制会增加成本并抑制主动性；沟通不是说完即完成，必须确认对方理解。',
      ['控制与计划的循环关系：计划提供标准，控制提供反馈，反馈又修正下一轮计划。若只考核销售额，销售可能压货给经销商，形成目标置换；若同时考核回款与客户满意度，行为会更均衡。指标设计要防止可测量性偏差，即只考核容易量化的部分而忽视真正重要的目标。', '沟通漏斗说明信息损耗：心中想100%，说出口80%，对方听到60%，听懂40%，记住20%。减少损耗的办法是结构化表达、可视化辅助、关键点重复与双向确认。跨部门冲突常源于目标与术语差异，可建立共同指标与定期联席会。对上行沟通，管理者要主动创造心理安全，避免坏消息被过滤。']
    ],
    ['创新与变革', '本章解决组织如何在延续现有业务的同时持续创新，以及如何管理变革阻力让新做法落地。',
      ['创新按程度分渐进式与突破式，按对象分产品、流程、商业模式与管理创新。', '创新来源包括客户需求、技术推动、跨界组合、边缘市场与内部创业。', '勒温变革模型为解冻、变革、再冻结，强调打破旧平衡并固化新行为。', '科特八步为紧迫感、联盟、愿景、沟通、授权、短期胜利、巩固与固化。', '变革阻力来自既得利益、习惯、认知偏差、组织惯性与能力不足。', '降低阻力可用沟通、参与、培训、试点、激励与必要时的时间安排。'],
      '先诊断阻力来源是利益还是能力，再选策略：利益受损用补偿与谈判，认知不足用沟通与试点，能力不足用培训与资源支持，最后用短期胜利建立信心。',
      '常认为变革失败都是沟通不够，或只改结构不改文化与激励。纠正方法是区分阻力类型，结构、流程、考核与文化要同步调整，否则旧激励会把新行为拉回原状。',
      ['科特八步的核心是顺序。先建立紧迫感，让组织认识到不变革的代价；再组建有权力的联盟；形成清晰愿景并反复沟通；授权清除障碍；设计可在半年内实现的短期胜利；用胜利巩固后续变革；最后把新做法写入制度与文化。跳过紧迫感直接宣布方案，往往遭遇软抵抗。', '试点是降低变革风险的有效方法。选择业务独立、领导支持、员工能力较强的单元先行试验，设定清晰指标与复盘节奏，成功后用数据说服其他单元。试点要注意避免特殊资源造成不可复制，也要防止试点单元被视为特权。推广阶段需配套培训、流程与考核，否则新做法难以固化。']
    ],
    ['管理案例', '本章训练用理论解释现象并提出可执行方案，重点是区分表象与根因、方案与指标。',
      ['案例分析四步为识别问题、理论诊断、方案比较、实施建议。', '常用框架有SWOT、波特五力、价值链、PEST、商业模式画布与7S。', '问题陈述要具体到主体、时间、表现与影响，避免把现象当问题。', '方案要写清做什么、谁负责、何时完成、需要什么资源、如何衡量。', '证据要区分事实、假设与观点，数据口径要说明来源与时间。', '结论要有优先级与取舍，明确风险与备选方案。'],
      '先列事实与时间线，提炼可验证的问题，再选一到两个框架做诊断，比较方案的成本收益与可行性，最后给出分阶段实施计划与关键指标。',
      '常把问题都归因于沟通不畅，或方案没有责任人与指标。纠正方法是用证据检验归因，至少列出两个竞争性解释；方案必须落到责任人、时间表与衡量标准，否则无法执行与验证。',
      ['以五力分析为例，不能只列五个名词。要判断每一力的强度及其证据：供应商集中度与替换成本决定议价能力；买方集中度与价格敏感度决定压价空间；新进入者受规模经济、品牌、渠道与政策壁垒约束；替代品看性价比与转换成本；现有竞争看集中度、增长与退出壁垒。最后要落到对利润池的影响。', '方案比较可用加权评分与风险矩阵。先列可行性、成本、收益、时间、风险五个维度并赋权，再对方案打分；随后用风险矩阵评估高影响低概率事件，准备应对措施。实施建议应分短期止血与长期建设，短期解决现金流与关键客户，长期解决能力与机制。缺少优先级的方案清单只是愿望。']
    ]
  ],

  '中级财务会计': [
    ['货币资金与应收', '本章解决流动性最强资产的真实性与应收款项的减值计量，是报表中最容易出现舞弊与错报的领域。',
      ['货币资金包括库存现金、银行存款与其他货币资金，现金限额一般为三至五天日常零星开支需要。', '银行存款余额调节表将企业账面余额与银行对账单余额调至相同，只核对未达账项，不作账务处理。', '应收账款按实际发生额入账，商业折扣按扣除后金额入账，现金折扣在新收入准则下作为可变对价冲减交易价格。', '坏账准备采用预期信用损失法，按单项或信用风险特征组合计提，借记信用减值损失、贷记坏账准备。', '实际核销坏账时借记坏账准备、贷记应收账款，已核销又收回的先恢复应收与坏账准备，再收款。', '应收票据贴现若不附追索权则终止确认，附追索权则按短期借款处理，贴现息计入财务费用。'],
      '月末先核对日记账与银行对账单，编制余额调节表查明未达账项；再按账龄或组合评估预期信用损失并计提坏账；票据贴现先判断追索权，最后检查报表是否按净额列示应收款项。',
      '常见错误是把调节表当作调账依据，或把坏账准备直接冲减应收账款。纠正方法是明确调节表只解决核对差异，未达账项待单据到达后入账；坏账准备是备抵账户，核销时才冲减应收，两者不能混同。',
      ['余额调节表可这样编：企业账面余额80万元，银行对账单余额85万元。经查企业已收银行未收6万元，企业已付银行未付3万元，银行已收企业未收2万元，银行已付企业未付4万元。企业侧调节为80加6减3等于83万元，银行侧调节为85加2减4等于83万元，两侧相等，说明未达账项已全部查明。调节表平衡只能证明未达账项处理完整，不能替代账实核对。', '预期信用损失的核心是提前确认风险。某企业应收账款按账龄组合计提：一年以内计提5%，一至二年计提10%，二至三年计提30%，三年以上计提50%。若各账龄余额分别为400万、200万、100万、50万，则应计提20加20加30加25等于95万元。原已计提60万元，本期补提35万元，借记信用减值损失、贷记坏账准备。若后续收回已核销款项，应恢复应收与坏账准备，再按正常收款处理。']
    ],
    ['存货', '本章解决存货成本的边界、发出计价与期末减值，是制造业与流通业利润操纵的常见切入点。',
      ['存货成本包括采购成本、加工成本和其他使存货达到目前场所和状态所发生的支出。', '非正常消耗的直接材料、直接人工与制造费用，以及一般仓储费用，不计入存货成本而计入当期损益。', '发出计价可采用先进先出法、月末一次加权平均法、移动加权平均法与个别计价法，不得采用后进先出法。', '可变现净值等于估计售价减估计销售费用、相关税费与进一步加工成本，不是售价本身。', '期末按成本与可变现净值孰低计量，成本高于可变现净值的差额计提存货跌价准备，影响因素消失可在原计提金额内转回。', '存货盘亏属于定额内损耗计入管理费用，自然灾害等非常损失计入营业外支出，管理不善造成的被盗丢失霉烂变质还需转出进项税额。'],
      '先按采购、加工、其他支出确定存货成本，再选择计价方法计算发出与结存成本，期末逐项比较成本与可变现净值并计提跌价准备，最后按账面价值列示报表并核对成本结转。',
      '常见错误是把售价直接当可变现净值，或已计提跌价准备的存货销售时忘记结转准备。纠正方法是可变现净值必须扣除销售费用、税费与进一步加工成本；销售时应同时结转主营业务成本与存货跌价准备，使成本按净额转出。',
      ['先进先出与加权平均在物价上涨时差异明显。某企业月初存货100件、单价10元，本月购入100件、单价14元，本月发出150件。先进先出法下发出成本为100乘10加50乘14等于1700元，期末结存50件成本700元；月末一次加权平均单价为(1000加1400)除以200等于12元，发出成本1800元，期末结存600元。先进先出法下当期利润较高、期末资产较高，加权平均法更平滑，选择应保持一致性。', '可变现净值要分是否需进一步加工。某企业库存原材料成本100万元，用于生产甲产品，甲产品估计售价160万元，进一步加工成本50万元，销售费用与税费10万元，则该材料可变现净值为160减50减10等于100万元，未减值。若甲产品售价降为150万元，可变现净值为90万元，应计提跌价准备10万元。若材料直接出售，则按材料自身售价减销售费用与税费计算，不能套用产品售价。']
    ],
    ['金融资产与长期股权投资', '本章解决金融资产按业务模式与合同现金流分类，以及长期股权投资按影响力选择成本法或权益法。',
      ['金融资产分类依据业务模式与合同现金流量特征，分为以摊余成本计量、以公允价值计量且变动计入其他综合收益、以公允价值计量且变动计入当期损益三类。', '交易性金融资产公允价值变动计入公允价值变动损益，处置时差额计入投资收益。', '其他债权投资公允价值变动计入其他综合收益，减值计入信用减值损失并对应其他综合收益，处置时累计其他综合收益转入投资收益。', '指定为以公允价值计量且变动计入其他综合收益的非交易性权益工具投资，处置时累计利得损失转入留存收益，不转入损益。', '长期股权投资中，对被投资单位控制采用成本法，对共同控制或重大影响采用权益法。', '权益法下初始投资成本小于应享有可辨认净资产公允价值份额的差额计入营业外收入，被投资方净利润份额确认投资收益并调整账面价值。'],
      '先看持股比例与是否存在控制、共同控制或重大影响选择长投方法，再按业务模式与合同现金流特征对金融资产分类，期末按分类计量，处置时特别注意其他综合收益的结转去向。',
      '常见错误是成本法下按被投资方净利润确认收益，或权益法下把收到的现金股利确认为投资收益。纠正方法是成本法只在被投资方宣告分红时确认投资收益，权益法按净利润份额确认收益、分红冲减长期股权投资账面价值。',
      ['权益法可举例说明。甲公司支付1000万元取得乙公司30%股权，取得时乙公司可辨认净资产公允价值为3500万元，甲公司应享有份额1050万元，初始成本小于份额的50万元计入营业外收入，同时调增长期股权投资至1050万元。当年乙公司实现净利润600万元，甲公司确认投资收益180万元，长投账面变为1230万元；乙公司宣告分派现金股利100万元，甲公司按份额收到30万元，冲减长投账面至1200万元。', '金融资产分类要看两个测试。合同现金流量特征测试要求合同现金流仅为本金和利息；业务模式测试看企业是以收取合同现金流为目标、以收取和出售为目标，还是其他。以收取为目标且通过现金流特征测试的债券投资分类为摊余成本；既收取又出售的分类为公允价值计量且变动计入其他综合收益；其余分类为以公允价值计量且变动计入当期损益。']
    ],
    ['固定资产与无形资产', '本章解决长期资产的资本化边界、折旧摊销政策与减值测试，核心是支出性质判断与寿命估计。',
      ['外购固定资产成本包括购买价款、相关税费、运输费、装卸费、安装费与专业人员服务费，可抵扣进项税额不计入。', '自建固定资产通过工程物资与在建工程归集，达到预定可使用状态时转入固定资产，符合资本化条件的借款费用计入成本。', '折旧方法有年限平均法、工作量法、双倍余额递减法与年数总和法，当月增加的固定资产当月不提、下月起提，当月减少的当月照提。', '后续支出符合资本化条件计入固定资产成本，日常修理费一般费用化，与存货生产加工相关的修理费按存货成本原则处理。', '固定资产减值按可收回金额低于账面价值的差额计提，可收回金额为公允价值减处置费用与预计未来现金流量现值孰高，减值不得转回。', '无形资产研究阶段支出费用化，开发阶段满足资本化条件的支出资本化；使用寿命有限的分期摊销，不确定的不摊销但每年减值测试。'],
      '先判断支出是否使资产达到预定可使用状态，再确定初始成本与折旧摊销政策，期末比较账面价值与可收回金额做减值测试，最后核对报表列示与附注披露。',
      '常见错误是设备已投入使用仍挂在在建工程，或把日常修理费资本化。纠正方法是达到预定可使用状态即转固并从下月起计提折旧；修理支出不延长寿命、不提高性能的应费用化，不得随意资本化调节利润。',
      ['双倍余额递减法可演示。设备原值100万元，预计使用5年，残值0.4万元，年折旧率为40%。第一年折旧40万元，账面60万元；第二年折旧24万元，账面36万元；第三年折旧14.4万元，账面21.6万元；最后两年改为直线法，每年折旧(21.6减0.4)除以2等于10.6万元。该方法前期费用高、后期低，适合技术更新快的资产。', '研发支出要分阶段。某企业研究阶段发生支出200万元，开发阶段发生支出300万元，其中符合资本化条件的250万元，另有注册费10万元。研究阶段200万元计入研发费用；开发阶段符合资本化条件的250万元加注册费10万元计入无形资产，其余50万元费用化。无形资产入账260万元，若使用寿命10年、无残值，则每月摊销约2.17万元，借记管理费用或制造费用、贷记累计摊销。']
    ],
    ['负债', '本章解决负债的确认时点、计量金额与利息费用归属，重点在职工薪酬、增值税与借款费用。',
      ['短期借款利息按月预提计入财务费用，实际支付时冲减应付利息；应付票据分商业承兑与银行承兑，带息票据期末计提利息。', '应付职工薪酬包括工资奖金津贴、社会保险费、住房公积金、职工福利费、辞退福利与股份支付，辞退福利一次性计入当期损益。', '一般纳税人增值税进项税额可抵扣，用于简易计税、免税项目、集体福利或个人消费以及非正常损失的进项税不得抵扣。', '借款费用资本化需同时满足资产支出已发生、借款费用已发生、购建活动已开始三个条件，达到预定可使用状态时停止资本化。', '应付债券按摊余成本计量，实际利率法确认利息费用，发行价格高于面值的差额为溢价，低于面值为折价。', '可转换公司债券应在初始确认时拆分为负债成分与权益成分，负债成分按未来现金流量现值计量。'],
      '先按负债类型确认入账金额，再判断利息费用应资本化还是费用化，月末计提职工薪酬与税费，最后核对报表列示与税会差异。',
      '常见错误是把进项税额与销项税额直接相抵后计入成本，或把辞退福利按受益对象分摊。纠正方法是进项税单独核算、不得计入采购成本；辞退福利不按受益对象分摊，一次性计入当期管理费用。',
      ['职工薪酬可举例。某企业本月工资总额100万元，其中生产工人60万元、车间管理人员15万元、行政管理人员25万元。单位承担社保16万元、公积金10万元，代扣个人社保8万元、个人所得税2万元。分配时借记生产成本60万元、制造费用15万元、管理费用25万元，贷记应付职工薪酬100万元；单位承担社保与公积金借记相应成本费用26万元，贷记应付职工薪酬26万元；发放时借记应付职工薪酬90万元，贷记银行存款90万元，同时冲减代扣款项。', '借款费用资本化要算准期间与金额。某企业为建造厂房专门借款1000万元，年利率6%，工程于3月1日开工，当年资本化期间为10个月。若闲置资金500万元用于短期投资，月收益0.2%，则资本化利息为1000乘6%乘10除以12等于50万元，减去闲置收益500乘0.2%乘10等于10万元，实际资本化40万元，其余利息费用化。若工程非正常中断超过3个月，中断期间应暂停资本化。']
    ],
    ['所有者权益与收入', '本章解决权益来源的分类列示与收入确认的五步法，是新准则下最常考也最容易出错的部分。',
      ['实收资本或股本按面值计入，投资者投入超过面值部分计入资本公积，资本公积可用于转增资本但不得弥补亏损。', '留存收益包括盈余公积与未分配利润；法定盈余公积按净利润10%提取，累计达到注册资本50%时可不再提取。', '收入确认五步法为识别合同、识别单项履约义务、确定交易价格、分摊交易价格、履行履约义务时确认收入。', '交易价格需考虑可变对价、重大融资成分、非现金对价与应付客户对价，可变对价计入金额不得超过极可能不发生重大转回的部分。', '合同负债核算企业已收或应收客户对价而尚未转让商品的义务，与预收账款在实务中按是否与合同相关区分。', '特定交易包括附销售退回、附质量保证、主要责任人与代理人、授予知识产权许可与售后回购，需按控制权判断确认时点与金额。'],
      '先判断合同是否成立并识别履约义务，再确定并分摊交易价格，最后按控制权转移时点或履约进度确认收入；权益业务按来源分别计入实收资本、资本公积与留存收益。',
      '常见错误是以开票或收款时点确认收入，或把合同负债与预收账款混用。纠正方法是收入确认只看控制权是否转移，不看结算方式；合同负债对应已收对价但尚未履约，预收账款更多用于非合同场景。',
      ['五步法可用设备加安装合同说明。合同总价100万元，设备单独售价80万元、安装单独售价20万元，两者可明确区分。设备于3月交付并经客户验收，安装于4月完成。交易价格按单独售价比例分摊，设备80万元、安装20万元。3月确认设备收入80万元并结转成本，4月安装完成确认20万元。若安装属于在某一时段内履行的履约义务，则应按完工进度确认，而不是等到完工一次确认。', '时段确认需满足三个条件之一：客户在企业履约同时即取得并消耗利益；客户能控制企业履约过程中的在建商品；企业履约产出不可替代且企业在整个合同期间有权就累计至今已完成的履约部分收取款项。某建筑合同总价1000万元，预计总成本800万元，第一年发生成本240万元，完工进度30%，则应确认收入300万元、结转成本240万元，合同毛利60万元。若进度无法可靠确定，则按已发生成本确认收入，直至成本可收回。']
    ],
    ['财务报告与调整', '本章解决报告期调整分录、日后事项处理与会计政策估计变更，确保报表可比与披露完整。',
      ['期末调整分录包括应计收入费用、递延收入费用、折旧摊销、资产减值与坏账计提。', '资产负债表日后事项分调整事项与非调整事项，调整事项调整报告年度报表，非调整事项只披露。', '调整事项包括诉讼案件结案、取得确凿证据证明资产减值、销售退回、发现舞弊或差错、董事会制定的利润分配方案中的现金股利。', '会计政策变更采用追溯调整法，累积影响数调整留存收益；无法合理确定累积影响数时采用未来适用法。', '会计估计变更采用未来适用法，不调整以前期间，也不计算累积影响数。', '重要前期差错采用追溯重述法，通过以前年度损益调整核算，不重要差错在本期直接更正。'],
      '先判断事项属于调整还是非调整、政策变更还是估计变更、重要差错还是不重要差错，再选择追溯调整、追溯重述或未来适用法，最后核对报表年初数与附注披露是否一致。',
      '常见错误是把日后事项一律调整报表，或把会计估计变更追溯调整。纠正方法是只有对报告期末已存在情况提供新证据的事项才调整；估计变更源于新信息，只能影响变更当期与未来期间。',
      ['日后事项可举例。某企业12月31日已对一起诉讼确认预计负债200万元，次年2月法院判决赔偿300万元。该事项在报告期末已存在，属于调整事项，应补确认负债与费用100万元并调整报告年度报表。若次年2月发生火灾损失500万元，火灾在报告期末并不存在，属于非调整事项，只在附注披露，不调整报告年度数字。若董事会于次年3月提出利润分配方案，现金股利作为非调整事项披露，股票股利在报表中处理需按准则规定。', '政策变更与估计变更的区分看本质。将存货发出计价由先进先出改为加权平均，属于会计政策变更，应追溯调整；将固定资产折旧年限由10年改为8年，属于会计估计变更，未来适用。将投资性房地产后续计量由成本模式改为公允价值模式，属于政策变更，追溯调整；将坏账计提比例由5%改为10%，属于估计变更。判断关键是变更的是确认计量基础还是对不确定性的判断。']
    ],
    ['中财实训', '本章检验能否把准则落到完整账套，重点在科目设置、税会差异、月末结转与报表勾稽的闭环。',
      ['完整账套流程为建账、日常分录、期末调整、结账与报表，期初余额必须试算平衡。', '重点科目包括应收账款与坏账准备、存货与跌价准备、固定资产与累计折旧、应付职工薪酬、应交税费与主营业务收入。', '税会差异常见于业务招待费、广告宣传费、公益性捐赠、罚款支出与国债利息，需在企业所得税汇算时调整。', '月末结转顺序为结转成本、计提税费与折旧、结转损益、结出本年利润、提取盈余公积。', '电算化要完成账套初始化、辅助核算设置、期初导入、凭证审核记账与月末结账。', '工作底稿应记录调整分录、计算过程与复核结论，保证数据可追溯。'],
      '按业务周期做一遍完整账套，用试算平衡、明细账与总账核对、三表勾稽三层自检；税会差异单独编制调整表，最后与申报表核对。',
      '常见错误是只做凭证不核对明细账，或月末先出表后补结转。纠正方法是每完成一类业务即核对明细账与总账，严格执行先结转损益再编表，报表不平先查凭证与结转而不是改表。',
      ['月末结账清单可列十二项：核对银行对账单、盘点现金与存货、计提折旧与摊销、计提坏账与存货跌价、计提工资社保与税费、分配制造费用、结转完工产品成本、结转销售成本、结转损益、计算所得税、提取盈余公积、编制报表。每项打勾并留计算底稿，可显著减少漏项。实训中常见问题是制造费用未分配、库存商品与主营业务成本不匹配、应交税费余额与申报表不符。', '税会差异要用例子理解。某企业利润总额500万元，业务招待费实际发生40万元，销售收入4000万元。招待费扣除限额为发生额60%即24万元，同时不超过销售收入5‰即20万元，取较低者20万元，纳税调增20万元。广告费发生700万元，扣除限额为销售收入15%即600万元，调增100万元可结转以后年度。国债利息收入20万元免税，调减20万元。调整后应纳税所得额为500加20加100减20等于600万元。']
    ]
  ],

  '成本会计': [
    ['成本会计基础', '本章界定成本对象、成本项目与费用界限，是全部成本归集分配工作的起点与规则来源。',
      ['成本对象可以是产品、批次、订单、作业、部门或客户，选择取决于管理需要与生产组织特点。', '成本项目一般设直接材料、直接人工与制造费用，也可增设燃料及动力、废品损失与停工损失。', '费用界限要划清五条：生产经营费用与非生产经营费用、生产成本与期间费用、各产品之间、完工产品与在产品之间、本期与下期之间。', '成本核算账户包括生产成本基本生产成本与辅助生产成本、制造费用、废品损失、停工损失。', '成本核算一般程序为确定对象与项目、归集分配要素费用、分配辅助生产与制造费用、计算完工与在产品成本、结转产品成本。', '成本会计制度有实际成本法、标准成本法与变动成本法，选择取决于核算目的与基础工作水平。'],
      '先明确成本对象与成本项目，再按受益原则设计归集与分配路径，划清五条费用界限，最后按品种法或分步法计算完工成本并结转。',
      '常见错误是把期间费用计入产品成本，或在不同成本对象之间直接比较单位成本。纠正方法是管理费用、销售费用、财务费用直接计入当期损益；不同对象的产品结构、批量与工艺不同，单位成本不可简单横比。',
      ['五条费用界限可用例子说明。企业购入办公用车属于非生产经营费用，不得计入产品成本；车间设备折旧计入制造费用，厂部办公楼折旧计入管理费用；同一车间生产甲乙两种产品，材料按定额消耗量分配；月末有在产品时，生产费用要在完工与在产品之间分配；预付明年保险费属于下期费用，通过预付账款递延。任何一条界限划错，都会导致产品成本失真与利润波动。', '品种法适用于大量大批单步骤生产或管理上不要求分步的多步骤生产。其特点是按月定期计算成本，成本计算期与会计期间一致；一般没有在产品或在产品数量很少，无需在完工与在产品之间分配；按产品品种设置成本明细账，归集全部生产费用。典型行业如发电、供水、采掘与部分化工企业。若企业同时生产多种产品但工艺相同，也可按品种分别归集。']
    ],
    ['要素费用归集与分配', '本章解决材料、人工、动力、折旧等要素费用如何按受益原则计入各成本对象，核心是分配标准的选择。',
      ['材料费用能直接确定对象的直接计入，共同耗用按定额消耗量、定额费用、产品重量或体积分配。', '人工费用计件工资直接计入，计时工资按实际工时或定额工时分配，车间管理人员工资计入制造费用。', '外购动力按仪表记录、机器功率时数或生产工时分配，照明用电一般计入制造费用或管理费用。', '折旧费按使用部门归属，生产车间计入制造费用，管理部门计入管理费用，销售部门计入销售费用。', '制造费用分配标准有生产工时、生产工人工资、机器工时与年度计划分配率法，标准应与费用动因相关。', '分配率等于待分配费用除以分配标准合计，尾差一般调整计入受益最大的对象。'],
      '先确定费用能否直接计入，不能直接计入的再选与消耗因果相关的分配标准，计算分配率与分配额，最后核对各对象分配额合计等于待分配费用。',
      '常见错误是分配标准与费用动因无关，或把尾差随意处理。纠正方法是机器设备折旧与维修按机器工时分配、人工相关费用按人工工时分配；尾差统一调整到金额最大的对象，保证分配额合计与总额一致。',
      ['材料定额消耗量分配可举例。某车间生产甲乙两种产品，共同耗用原材料6000千克，单价10元，甲产品定额消耗4000千克、乙产品定额消耗2000千克。分配率为6000除以6000等于1千克每定额千克，甲分配4000千克、乙分配2000千克，金额分别为4万元与2万元。若按实际产量分配而产品单位消耗差异大，就会把耗料多的产品成本低估，因此定额消耗量比产量更贴近动因。', '制造费用年度计划分配率法适合季节性生产。某车间全年计划制造费用120万元，全年计划产量按定额工时计算为6万小时，计划分配率为20元每小时。1月实际发生8万元，实际工时5000小时，按计划分配10万元，分配后制造费用账户出现贷方余额2万元，表示少分配；年末统一调整，多分配额冲减产品成本，少分配额补记产品成本，季节性波动因此被平滑。']
    ],
    ['完工产品与在产品', '本章解决生产费用如何在完工产品与月末在产品之间划分，核心是约当产量与投料程度的判断。',
      ['常用方法包括不计算在产品成本、按年初数固定计算、在产品按所耗直接材料计价、约当产量法、在产品按完工产品成本计价、定额成本法与定额比例法。', '不计算在产品成本法适用于月末在产品数量很小，按年初数固定法适用于各月在产品数量稳定。', '约当产量等于在产品数量乘完工程度，完工程度按累计工时定额占完工产品工时定额的比例计算。', '材料在生产开始时一次投入的，投料程度为100%；陆续投入的按投料定额比例计算，与加工完工程度可能不同。', '约当产量法分配率等于月初在产品成本加本月发生费用，除以完工产品数量加月末在产品约当产量。', '完工产品成本等于月初在产品成本加本月发生费用减月末在产品成本。'],
      '先盘点在产品数量并确定完工程度，再分别计算材料与加工费的约当产量，按成本项目计算分配率，最后算出完工与在产品成本并核对总额。',
      '常见错误是把材料与加工费使用同一个完工程度，或把在产品数量直接当约当产量。纠正方法是材料按投料程度、加工费按累计工时完工程度分别计算；约当产量必须乘完工程度，不能直接用实物数量。',
      ['约当产量可举例。某产品本月完工800件，月末在产品200件，完工程度50%。月初与本月发生的加工费合计为90000元。加工费约当产量为800加200乘50%等于900件，分配率为90000除以900等于100元每件，完工产品负担80000元，在产品负担10000元。若材料在生产开始时一次投入，材料约当产量为800加200等于1000件，材料成本按1000件分配，不能按900件计算。', '定额比例法适合定额管理基础较好的企业。某产品完工800件、在产品200件，材料定额单耗10千克、单价5元，加工费定额工时4小时、每小时费用20元。材料定额总耗为(800加200)乘10等于10000千克，实际材料费用48000元，分配率4.8元每千克，完工产品材料成本38400元、在产品9600元。加工费按定额工时计算，完工3200小时、在产品按完工程度折合400小时，分配率按实际费用除以定额工时合计求得。']
    ],
    ['产品成本计算方法', '本章按生产组织与工艺特点选择品种法、分批法、分步法，解决多步骤生产的成本归集与结转。',
      ['品种法适用于大量大批单步骤生产或管理上不要求分步的多步骤生产，按月定期计算，成本计算期与会计期间一致。', '分批法适用于单件小批或按订单生产，成本计算期与生产周期一致，与会计期间不一致，一般不需要在完工与在产品间分配。', '分步法适用于大量大批多步骤生产，分逐步结转分步法与平行结转分步法。', '逐步结转分步法计算各步骤半成品成本，综合结转时需进行成本还原，分项结转则按成本项目直接结转。', '平行结转分步法不计算半成品成本，各步骤只归集本步骤费用，按广义在产品计算份额，最后平行汇总计入产成品。', '分类法按产品类别归集成本再按系数分配，定额法以定额成本为基础加脱离定额差异与定额变动差异。'],
      '先看生产类型是大量大批还是单件小批、工艺是否分步，再选方法；分步法要判断是否需要半成品成本与成本还原，最后核对各步骤成本与产成品成本衔接。',
      '常见错误是分批法下把期间费用计入订单成本，或逐步结转综合结转后忘记成本还原。纠正方法是期间费用不计入订单成本；综合结转的半成品成本包含上步骤利润与费用，必须按成本项目还原，否则产成品结构失真。',
      ['逐步结转分步法可演示。某产品经两个步骤加工，第一步骤完工半成品成本为材料40万元、加工20万元，共60万元转入第二步骤；第二步骤发生加工30万元，产成品成本为90万元。综合结转下第二步骤半成品项目60万元、加工30万元。成本还原以产成品中半成品成本60万元按第一步骤成本结构还原为材料40万元、加工20万元，最终产成品成本结构为材料40万元、加工50万元。若不还原，会把上步骤加工费误当材料。', '平行结转分步法的关键在广义在产品。某产品经两步加工，第一步骤本月费用50万元，第二步骤本月费用30万元。月末第一步骤在产品20件、第二步骤在产品10件，产成品100件。第一步骤广义在产品包括本步骤在产品20件与第二步骤在产品10件，共30件；第二步骤广义在产品仅本步骤10件。各步骤按自身份额计算应计入产成品的成本，最后平行汇总，无需结转半成品。']
    ],
    ['标准成本与差异分析', '本章把实际成本与标准成本的差距拆成价格差异与数量差异，用于责任归属与成本控制。',
      ['标准成本分理想标准与正常标准，正常标准考虑合理损耗与不可避免的低效，更适合考核。', '直接材料价格差异等于实际价格减标准价格乘实际用量，用量差异等于实际用量减标准用量乘标准价格。', '直接人工工资率差异等于实际工资率减标准工资率乘实际工时，效率差异等于实际工时减标准工时乘标准工资率。', '变动制造费用耗费差异按实际分配率减标准分配率乘实际工时，效率差异按工时差异乘标准分配率。', '固定制造费用三差异为耗费差异、闲置能量差异与效率差异；两差异为预算差异与能量差异。', '差异处理可结转本期损益，也可按比例分摊到存货与销货成本，选择应与核算政策一致。'],
      '先确定标准用量与标准价格，再按实际减标准逐项拆解差异，价格类差异用实际用量、数量类差异用标准价格，最后按责任部门归类并分析可控性。',
      '常见错误是把价格差异与数量差异的乘数用反，或把固定制造费用按变动费用方法分析。纠正方法是价格差异乘实际用量、数量差异乘标准价格；固定制造费用要单独区分预算与产能利用，不能简单套用变动费用公式。',
      ['直接材料差异可举例。标准单价10元、标准用量每件5千克，本月生产1000件，实际耗用5200千克、实际单价9.5元。价格差异为(9.5减10)乘5200等于负2600元，属于节约；用量差异为(5200减5000)乘10等于2000元，属于超支；总差异为负600元。价格节约可能来自采购议价，用量超支可能来自操作浪费，责任分别落在采购部门与生产部门，不能只看总差异。', '固定制造费用三差异可用数据说明。预算固定制造费用120万元，预算工时6000小时，标准分配率20元每小时；实际固定制造费用125万元，实际工时5500小时，实际产量标准工时5000小时。耗费差异为125减120等于5万元；闲置能量差异为(6000减5500)乘20等于10万元；效率差异为(5500减5000)乘20等于10万元；总差异25万元。耗费差异反映费用控制，闲置能量反映产能利用不足，效率差异反映工时效率。']
    ],
    ['作业成本法', '本章按作业动因分配间接费用，解决传统人工工时法在间接费用高、产品多样时严重扭曲成本的问题。',
      ['作业成本法路径为资源到作业再到产品，先把资源成本归集到作业，再按作业动因分配到产品。', '资源动因解释资源如何被作业消耗，作业动因解释产品如何消耗作业，两者不能混同。', '作业按层级分单位级、批次级、产品级与设施级，层级越高越难直接追溯到单个产品。', '计算步骤为识别作业、归集作业成本、选择成本动因、计算动因分配率、分配至产品并汇总。', '适用条件是间接费用比重大、产品种类多、批量差异大、生产准备与检验等作业频繁。', '局限在于作业划分与动因选择主观、维护成本高，单一产品或高度标准化生产未必适用。'],
      '先识别主要作业并归集资源成本，再选与消耗因果相关的动因计算分配率，最后汇总各产品作业成本并与传统法比较，判断扭曲程度。',
      '常见错误是作业划分越细越好，或选择与消耗无关的动因。纠正方法是按重要性原则合并同质作业，动因必须能解释消耗差异；作业过细会增加核算成本而收益有限。',
      ['作业成本法可举例。某企业生产甲、乙两种产品，传统法按机器工时分配制造费用。甲产量1000件、工时2000小时，乙产量100件、工时2000小时，制造费用40万元，传统法各分20万元，甲单位20元、乙单位200元。若按作业法，设备调试20次甲5次、乙15次，调试成本15万元，按次数分配甲3.75万元、乙11.25万元；检验批次甲10批、乙30批，检验成本10万元，按批次分配甲2.5万元、乙7.5万元。其余15万元按机器工时平均分配，甲乙各7.5万元；甲合计13.75万元、乙合计26.25万元，乙单位成本2625元，传统法明显低估了小批量产品的成本。', '作业成本法不是万能。若企业产品单一、间接费用占比低、生产高度稳定，传统工时法误差有限，引入作业成本法反而增加核算负担。判断适用性可看三个信号：间接费用占产品成本比重是否超过30%，产品多样性与批量差异是否明显，价格竞争是否激烈到需要精确成本。实施时应先做试点，比较作业法与现有方法的成本差异，再决定推广范围。']
    ],
    ['成本控制与决策', '本章用相关成本与增量分析支持短期决策，解决特殊订单、自制外购与亏损产品去留问题。',
      ['相关成本包括增量成本、机会成本、可避免成本与专属成本；沉没成本、共同固定成本通常不相关。', '特殊订单决策在闲置产能条件下，只要价格高于单位变动成本且不违反法规，接受订单可增加利润。', '自制外购决策比较外购价格与自制相关成本，自制需考虑机会成本、质量成本与产能限制。', '亏损产品是否停产看贡献毛益，贡献毛益为正且无法转产时继续生产可弥补固定成本。', '目标成本等于竞争性市场价格减目标利润，再倒推设计、采购与制造成本。', '生命周期成本包括研发、设计、制造、营销、售后与处置成本，避免只看制造成本。'],
      '先剔除沉没成本与共同固定成本，再比较各方案的增量收入与增量成本，有产能限制时加入机会成本，最后结合长期战略与质量因素判断。',
      '常见错误是用单位完全成本比较特殊订单价格，或认为亏损产品一定应停产。纠正方法是短期决策看变动成本与贡献毛益，固定成本只要不因决策改变就不相关；停产会失去贡献毛益并可能引发连锁影响。',
      ['特殊订单可举例。某企业正常售价100元，单位变动成本60元，单位固定成本20元，当前产能利用率80%。现有一批订单报价70元、数量1万件。按完全成本80元看似乎亏损，但固定成本不因订单增加而改变，单位贡献毛益10元，接受订单增加利润10万元。若订单需要专用设备租金3万元，则相关增量利润为7万元，仍可接受。若产能已满，需减少正常销售，则机会成本为放弃的贡献毛益，决策结论可能反转。', '自制外购要看相关成本。某零件外购价25元，自制单位变动成本18元，分摊固定成本8元，表面自制成本26元高于外购。但固定成本不论自制与否都会发生，相关成本只有18元，自制更优。若自制需占用可出租的厂房，年租金收入20万元，年产零件5万件，则每件机会成本4元，自制相关成本22元，仍低于外购25元；若租金收入为40万元，每件机会成本8元，自制相关成本26元，应改为外购。']
    ],
    ['成本报表与分析', '本章用成本报表与因素分析定位成本变动原因，把核算数据转化为管理改进依据。',
      ['成本报表包括全部产品生产成本表、主要产品单位成本表、制造费用明细表与期间费用明细表。', '可比产品成本降低额等于上年实际平均单位成本减本年实际单位成本乘本年产量，降低率等于降低额除以上年成本。', '产值成本率等于产品成本除以工业总产值，用于反映投入产出效率。', '连环替代法按固定顺序逐项替换因素，每次只替换一个因素，差额即为该因素影响。', '成本习性分析把成本分为变动、固定与混合，可用高低点法或回归分析分解。', '成本考核以责任成本为核心，只考核责任中心可控成本，避免不可控因素影响评价。'],
      '先做趋势与结构分析看总体变化，再按产品与成本项目拆解，用连环替代法量化产量、单价、用量与效率的影响，最后落实到责任部门与改进措施。',
      '常见错误是连环替代不固定顺序导致结果不可比，或把成本降低额直接等同于利润增加额。纠正方法是事先约定替换顺序并保持一致；成本降低只有在其销售实现且售价不变时才带来利润增加。',
      ['连环替代可演示。某产品材料成本为产量乘单耗乘单价，上年为1000乘5乘10等于5万元，本年为1100乘4.8乘11等于5.808万元，增加0.808万元。按产量、单耗、单价顺序替换：产量影响为(1100减1000)乘5乘10等于0.5万元；单耗影响为1100乘(4.8减5)乘10等于负0.22万元；单价影响为1100乘4.8乘(11减10)等于0.528万元；合计0.808万元。顺序改变会得到不同分解值，因此报告要说明替换顺序。', '成本报表分析要结合业务解释。若单位成本上升，先看材料单价、单耗与产品结构；材料涨价属外部因素，单耗上升属可控因素；若产量下降而固定成本不变，单位固定成本上升属产能利用问题。考核时应区分可控与不可控，原材料涨价不应简单归责于车间。分析结论要落到采购策略、工艺改进或产能安排，而不是停留在数字对比。']
    ]
  ],

  '经济法': [
    ['法律基础与经济法概述', '本章建立法律渊源、法律关系与责任形式的基础框架，为后续公司、合同、票据与税法的适用提供方法。',
      ['法律渊源按效力从高到低为宪法、法律、行政法规、地方性法规、规章，下位法不得与上位法冲突。', '同一层级特别法优于一般法、新法优于旧法；不能确定适用时由有权机关裁决。', '法律关系三要素为主体、客体与内容，主体包括自然人、法人与非法人组织，客体包括物、行为、智力成果与人身利益。', '法律事实分事件与行为，事件不以人的意志为转移，行为以意思表示为要素。', '经济法调整市场主体、市场秩序、宏观调控与社会保障关系，区别于调整平等主体财产关系的民法。', '法律责任分民事、行政与刑事，诉讼时效一般为三年，最长权利保护期间为二十年。'],
      '先判断法律关系性质与主体地位，再找对应法律规范的效力层级，确认法律事实与时间节点，最后确定责任形式与救济途径。',
      '常见错误是把经济法理解为与经济有关的法，或忽略诉讼时效与除斥期间的区别。纠正方法是按调整对象区分部门法；诉讼时效影响胜诉权，除斥期间届满则实体权利消灭。',
      ['法律效力冲突可用例子说明。某地方性法规规定罚款上限高于法律，适用时应以法律为准，因为下位法不得与上位法冲突。若同一事项新颁布的行政法规与旧法律不一致，不能简单按新法优于旧法处理，而应看制定机关与效力层级，必要时报请有权机关裁决。考试中先比较效力层级，再比较特别法与一般法，最后才看新旧。', '诉讼时效与除斥期间不同。甲对乙享有货款债权，约定2020年1月1日到期，甲直到2024年才起诉，乙可提出诉讼时效抗辩，但债权本身不消灭，乙自愿履行后不得反悔。若甲因欺诈享有撤销权，自知悉之日起一年内不行使，撤销权消灭，这是除斥期间，不发生中止中断。区分方法是看期间届满消灭的是胜诉权还是形成权本身。']
    ],
    ['公司法', '本章解决公司资本制度、治理结构与股东责任，核心是认缴出资、决议规则与法人人格否认。',
      ['有限责任公司与股份有限公司在设立方式、资本表现形式与股权流动性上不同，有限责任公司更强调人合性。', '有限责任公司注册资本实行认缴登记制，全体股东认缴的出资额应自公司成立之日起五年内缴足。', '出资形式包括货币、实物、知识产权、土地使用权、股权与债权等，劳务与信用不能作为出资。', '治理结构为股东会、董事会、审计委员会或监事会、经理层，规模较小的公司可设一名董事不设董事会。', '股东会特别决议事项包括修改章程、增减注册资本、合并分立解散或变更公司形式，需经代表三分之二以上表决权的股东通过。', '法人人格否认适用于股东滥用法人独立地位和股东有限责任逃避债务，严重损害债权人利益，股东对公司债务承担连带责任。'],
      '先确定公司类型与章程约定，再判断决议是否属于特别决议、召集程序与表决比例是否合法，最后确定责任主体是公司、股东还是董事高管。',
      '常见错误是认为认缴就是不缴，或认为股东有限责任绝对化。纠正方法是认缴出资有五年缴足期限，未届期但公司不能清偿到期债务时可能加速到期；滥用独立地位与人格混同可被揭开面纱。',
      ['决议效力分三种情形。某有限责任公司股东会未通知某股东即作出增资决议，召集程序违法，该股东可自决议作出之日起六十日内请求法院撤销；若决议内容违反法律强制性规定，则自始无效；若根本没有召开股东会而伪造决议，则决议不成立。三种情形的法律后果与起诉期限不同，答题要先判断属于不成立、无效还是可撤销，再写救济方式。', '法人人格否认可用资金混同说明。甲公司股东张某将公司货款转入个人账户用于购房，公司账目与个人账目不分，导致公司无法清偿供应商货款。供应商可主张张某滥用公司独立地位，要求其对债务承担连带责任。该责任是个案否认，不影响公司其他交易的法人资格。若张某已足额出资且财产独立，仅公司经营亏损，则不能要求其承担连带责任。']
    ],
    ['合同法', '本章按订立、效力、履行、违约的链条适用合同规则，重点是效力状态与违约救济的选择。',
      ['要约需内容具体确定并表明经受要约人承诺即受约束，要约邀请不具备约束力，如拍卖公告与招股说明书。', '承诺生效时合同成立，承诺内容应与要约一致，实质性变更构成新要约。', '合同效力分有效、无效、可撤销与效力待定；无效情形包括违反强制性规定、违背公序良俗、恶意串通与虚假意思表示。', '可撤销情形包括重大误解、欺诈、胁迫与显失公平，撤销权应通过诉讼或仲裁行使。', '履行抗辩权包括同时履行抗辩、先履行抗辩与不安抗辩，不安抗辩要求有确切证据证明对方丧失履行能力。', '违约责任包括继续履行、采取补救措施、赔偿损失、违约金与定金；违约金过分高于损失可请求适当减少，定金不得超过主合同标的额百分之二十。'],
      '先判断合同是否成立与生效，再审查是否存在无效或可撤销事由，履行阶段看抗辩权是否成立，最后按违约形态选择继续履行、赔偿或违约金调整。',
      '常见错误是把要约邀请当要约，或认为可撤销合同无需行使就自动无效。纠正方法是看内容是否具体确定与是否表明受约束；可撤销合同在撤销前有效，须在除斥期间内通过诉讼或仲裁撤销。',
      ['违约金调整可举例。合同约定违约金100万元，实际损失30万元，违约方请求调减。司法实践一般以实际损失为基础，兼顾合同履行情况、当事人过错与预期利益，违约金超过损失百分之三十的部分通常可认定为过分高于损失。若约定违约金低于实际损失，守约方可请求增加至损失额。定金与违约金不能并用，守约方只能选择其一，定金不足以弥补损失时可请求赔偿超过定金部分。', '不安抗辩权适用有严格条件。甲先履行交货义务，发现乙经营状况严重恶化、转移财产逃避债务或有丧失商业信誉的情形，且有确切证据，甲可中止履行并通知乙；乙在合理期限内未恢复履行能力且未提供适当担保的，甲可解除合同。若甲无确切证据即中止履行，应承担违约责任。这与先履行抗辩权不同，后者是后履行方在先履行方未履行时拒绝自己的履行。']
    ],
    ['票据与支付结算法', '本章掌握票据的要式性、无因性与流通规则，重点是背书连续、票据权利与抗辩。',
      ['我国票据包括汇票、本票与支票，本票仅为银行本票，支票分现金支票、转账支票与普通支票。', '票据行为包括出票、背书、承兑与保证，均需签章并记载法定事项，欠缺绝对必要记载事项票据无效。', '背书应连续，前手背书人与后手被背书人名称依次衔接，背书不连续持票人不能证明权利。', '票据权利包括付款请求权与追索权，付款请求权是第一次权利，追索权是第二次权利。', '票据抗辩分对物抗辩与对人抗辩，持票人善意且支付对价时可切断对人抗辩。', '追索权期限：对承兑人与出票人自到期日起二年，对支票出票人自出票日起六个月，对前手自被拒绝之日起六个月。'],
      '先检查票据形式是否完备、背书是否连续，再判断持票人是否善意取得，最后确定付款请求权或追索权的行使对象与期限。',
      '常见错误是认为票据无因就意味着可以脱离基础关系任意主张，或忽略背书连续的形式要求。纠正方法是无因性保护善意持票人，直接当事人之间仍可依基础关系抗辩；背书不连续需补齐证明。',
      ['背书连续可举例。票据出票人记载收款人为甲公司，甲公司背书转让给乙公司，乙公司背书转让给丙公司，丙公司向银行提示付款。若乙公司背书时在被背书人栏误写为丁公司，而丁公司又背书给丙公司，则形式上形成甲到乙、乙到丁、丁到丙的连续链条，丙可主张权利；若中间缺少乙到丁的背书，则背书不连续，丙需证明取得票据的合法性。背书记载不得转让的，后手再背书转让，原背书人对后手的被背书人不承担保证责任。', '票据抗辩的切断可用案例说明。甲公司因买卖合同签发汇票给乙公司，乙公司背书转让给不知情的丙公司并收取对价。后甲公司发现乙公司未交货，能否以基础关系对抗丙公司？因丙公司善意且支付对价，甲公司不得以对乙公司的抗辩对抗丙公司，仍应付款；甲公司可另向乙公司主张违约赔偿。若丙公司是无对价取得票据或明知乙公司违约，则抗辩不被切断。']
    ],
    ['税法基础', '本章掌握增值税、企业所得税与个人所得税的纳税人、计税依据与优惠，重点是税基计算与纳税义务时间。',
      ['增值税一般纳税人适用13%、9%、6%三档税率，小规模纳税人适用征收率，优惠按现行政策执行。', '一般计税应纳税额等于当期销项税额减当期进项税额，销售额为不含税销售额，价外费用并入销售额。', '进项税额不得抵扣的情形包括用于简易计税、免税项目、集体福利或个人消费，以及非正常损失的购进货物。', '企业所得税应纳税所得额等于收入总额减不征税收入、免税收入、各项扣除与允许弥补的以前年度亏损。', '扣除限额常见规定：业务招待费按发生额60%且不超过销售收入5‰，广告宣传费一般不超过销售收入15%，公益性捐赠不超过年度利润总额12%。', '个人所得税综合所得包括工资薪金、劳务报酬、稿酬与特许权使用费，按年合并适用3%至45%超额累进税率，专项附加扣除包括子女教育、继续教育、大病医疗、住房贷款利息或租金、赡养老人与婴幼儿照护。'],
      '先确定税种与纳税人身份，再算计税依据与适用税率，逐项检查扣除限额与不得抵扣项目，最后确认纳税义务发生时间与申报期限。',
      '常见错误是把含税销售额直接乘税率，或把不征税收入与免税收入混同。纠正方法是先价税分离再计算销项；不征税收入不属于征税范围，免税收入属于征税范围但免征，二者税务处理不同。',
      ['增值税可举例。某一般纳税人销售货物取得含税收入113万元，适用13%税率，销项税额为113除以1.13乘13%等于13万元。当月购进原材料取得专用发票，金额60万元、进项税7.8万元，支付运输费含税10.9万元、税率9%，进项税0.9万元。应纳税额为13减7.8减0.9等于4.3万元。若购进的原材料用于集体福利，则进项税不得抵扣，已抵扣的需转出。', '企业所得税调整可举例。某企业利润总额500万元，业务招待费40万元、销售收入4000万元，扣除限额为24万元与20万元中的较低者20万元，调增20万元；广告费700万元，限额600万元，调增100万元；国债利息20万元免税，调减20万元；税收滞纳金5万元不得扣除，调增5万元。应纳税所得额为500加20加100减20加5等于605万元，按25%税率计算应纳税额151.25万元。']
    ],
    ['证券与破产法', '本章解决证券发行交易的信息披露义务与破产程序的清偿顺序，重点是重整与清算的选择。',
      ['证券公开发行需依法注册，发行人应披露招股说明书、募集说明书与定期报告，保证真实准确完整。', '禁止内幕交易、操纵市场、虚假陈述与欺诈客户，违法者承担行政、民事与刑事责任。', '破产程序包括申请与受理、指定管理人、债权申报、债权人会议、重整或和解、破产清算。', '债权申报期限自法院发布受理公告之日起计算，最短三十日、最长三个月，逾期申报可在破产财产最后分配前补充申报。', '清偿顺序为破产费用与共益债务随时清偿，其次是职工债权，再次是社会保险费用与税款，最后是普通债权。', '有财产担保的债权就特定财产优先受偿，但重整期间担保权暂停行使，重整不成功则转入清算。'],
      '先判断程序阶段与主体资格，再确认债权性质与担保情况，按法定顺序计算清偿比例，最后比较重整与清算对债权人的回收率。',
      '常见错误是把重整等同于清算，或认为有担保债权可以完全脱离破产程序。纠正方法是重整重在挽救营业，清算重在分配财产；担保权在重整期间受限制，且担保物价值不足部分转为普通债权。',
      ['清偿顺序可举例。某企业破产财产500万元，破产费用与共益债务50万元，拖欠职工工资与补偿金150万元，欠缴社保与税款100万元，普通债权600万元，另有以厂房抵押的银行贷款200万元，厂房变现150万元。首先支付破产费用50万元；抵押债权就厂房变现150万元优先受偿，未受偿50万元转为普通债权；剩余财产300万元支付职工债权150万元、社保税款100万元，余50万元按普通债权比例分配。普通债权总额为600加50等于650万元，清偿率约为7.69%。', '重整与清算的选择看营运价值。若企业只是流动性危机但主业有竞争力，重整可通过债务重组、引入投资人与经营调整保留营运价值，债权人回收率可能高于清算；若设备专用、客户流失、继续经营亏损扩大，清算更可取。重整计划需经债权人会议分组表决通过并经法院批准，部分表决组未通过时符合条件可强制批准，但需保证反对组获得的清偿不低于清算所得。']
    ],
    ['会计法规与责任', '本章明确会计资料真实性责任、会计机构设置与注册会计师执业规范，区分会计责任与审计责任。',
      ['各单位必须依法设置会计账簿，保证真实完整，不得以虚假经济业务或资料进行会计核算。', '单位负责人对本单位会计工作和会计资料的真实性、完整性负责，不是仅由会计人员承担。', '会计人员应具备专业能力，出纳不得兼管稽核、会计档案保管以及收入、支出、费用、债权债务账目的登记。', '代理记账机构需依法设立，委托单位仍需对会计资料真实性完整性负责。', '注册会计师应遵守独立性与审计准则，对财务报表是否公允反映发表意见，承担审计责任。', '会计违法责任包括行政责任与刑事责任，伪造变造会计凭证、隐匿或故意销毁依法应保存的会计资料可构成犯罪。'],
      '先看行为违反哪部法律与哪项义务，再确定责任主体是单位、负责人、会计人员还是注册会计师，最后判断责任类型与后果。',
      '常见错误是把会计责任推给会计师事务所，或认为单位负责人只负领导责任。纠正方法是会计责任由被审计单位承担，审计责任由注册会计师承担，二者不能替代；单位负责人是会计资料真实完整的第一责任人。',
      ['会计与审计责任可举例。某公司管理层虚构收入导致报表重大错报，注册会计师因未执行必要函证程序未发现。公司承担会计责任，需更正报表并接受处罚；注册会计师若未保持职业怀疑、未按准则执行程序，承担审计责任。若注册会计师已按准则执行仍未能发现精心策划的舞弊，不能简单认定其承担全部责任，但需证明程序充分适当。', '会计违法后果要区分情节。单位私设会计账簿，由财政部门责令限期改正、罚款，对直接负责的主管人员与其他直接责任人员处罚款；伪造变造会计凭证、编制虚假财务报告，情节严重的可构成违规披露、不披露重要信息罪或提供虚假证明文件罪。会计人员因违法被处罚的，还可能被记入信用记录，影响执业。']
    ],
    ['经济法案例', '本章训练把法条适用于事实，重点是请求权基础、时间线与责任形式的完整表达。',
      ['案例分析采用三段论：大前提为法律规范，小前提为案件事实，结论为法律责任。', '先理清主体关系与时间线，再确定请求权基础，是合同、侵权、公司还是票据关系。', '答题要写明法律依据、构成要件、事实对应与责任形式，不能只给结论。', '举证责任一般由主张者承担，特殊侵权与公司纠纷存在举证责任倒置或分配调整。', '常见领域包括公司治理与股东责任、合同效力与违约、票据抗辩、破产清偿与消费者保护。', '结论要可执行，写明赔偿金额、履行方式、期限或救济途径。'],
      '先列事实与时间线，标注关键节点与主体，再找请求权基础并逐项检验构成要件，最后写出责任形式与计算过程，检查是否遗漏抗辩事由。',
      '常见错误是只写违法不给依据，或忽略诉讼时效与除斥期间。纠正方法是每个结论后附法条依据与要件对应；审查时间节点，区分胜诉权消灭与实体权利消灭。',
      ['公司案例可按要件展开。甲为乙公司股东，未足额出资即转让股权，公司不能清偿债务。债权人可主张甲在未出资本息范围内对公司债务不能清偿部分承担补充赔偿责任，受让人知道或应当知道的承担连带责任。答题顺序为：确认公司不能清偿到期债务，确认甲未履行出资义务，确认转让时间与受让人知情状态，最后写出责任范围与顺位。', '合同案例要区分效力与违约。甲将房屋卖给乙并交付，未办理过户，后又卖给丙并办理过户。乙可主张甲违约，要求赔偿损失，但不能对抗已登记的丙；若乙已占有房屋，可依占有主张相关权利。若甲乙恶意串通损害丙利益，合同无效。答题时要先判断合同效力，再判断物权变动，最后确定违约救济，不能把合同有效与物权变动混为一体。']
    ]
  ],

  '高级财务会计': [
    ['合并报表基础', '本章解决合并范围与控制判断，明确同一控制与非同一控制下企业合并的不同处理逻辑。',
      ['控制三要素为对被投资方的权力、通过参与相关活动享有的可变回报、有能力运用权力影响回报金额。', '合并范围以控制为基础，持股比例不是唯一标准，半数以下也可能控制，半数以上也可能不控制。', '同一控制下企业合并采用权益结合法，按被合并方所有者权益账面价值份额入账，差额调整资本公积，不产生商誉。', '非同一控制下企业合并采用购买法，合并成本按付出对价的公允价值，可辨认净资产按购买日公允价值计量。', '合并程序为统一会计政策与期间、编制调整分录、抵销内部交易、汇总报表、计算少数股东权益与损益。', '少数股东权益在所有者权益项下单独列示，少数股东损益在净利润项下单独列示。'],
      '先按控制三要素判断是否纳入合并范围，再区分同一控制与非同一控制确定合并成本与差额去向，最后统一政策、编制抵销分录并核对少数股东权益。',
      '常见错误是仅按持股比例判断合并范围，或把同一控制合并差额计入商誉。纠正方法是结合协议、表决权与可变回报综合判断控制；同一控制差额调整资本公积，只有非同一控制才可能产生商誉。',
      ['控制判断可用案例说明。甲公司持有乙公司40%股权，其余股权分散于众多小股东，甲公司通过股东协议受托行使另外15%的表决权，且有权任免乙公司多数董事，则甲公司虽未过半数仍构成控制，应将乙公司纳入合并范围。反之，若甲公司持股55%，但章程规定重大事项需全体股东一致同意，且甲公司无法主导相关活动，则可能不构成控制。判断核心是权力与回报的联结。', '同一控制与非同一控制的差异可用数字说明。甲、乙同受丙控制，甲公司以800万元取得乙公司100%股权，乙公司净资产账面价值600万元，差额200万元冲减资本公积，资本公积不足冲减的调整留存收益。若甲乙无关联，乙公司可辨认净资产公允价值700万元，合并成本800万元，则确认商誉100万元。同一控制不确认新的资产增值，非同一控制按公允价值确认并可能产生商誉。']
    ],
    ['合并抵销与商誉', '本章解决长期股权投资与子公司权益的抵销、内部交易未实现损益的消除，以及商誉的计算与减值。',
      ['权益抵销分录为借记子公司股本、资本公积、盈余公积、未分配利润与商誉，贷记母公司长期股权投资与少数股东权益。', '内部存货交易抵销未实现损益，期末存货中包含的未实现利润借记营业成本、贷记存货。', '内部固定资产交易抵销未实现损益，并调整多计提的折旧；连续编制时调整期初未分配利润。', '内部债权债务抵销借记应付账款、贷记应收账款，同时抵销对应坏账准备与信用减值损失。', '商誉等于合并成本减应享有购买日可辨认净资产公允价值份额，负商誉计入当期营业外收入。', '商誉不摊销，至少每年进行减值测试，减值损失计入当期损益且不得转回。'],
      '先做权益抵销，再抵销内部往来与未实现损益，计算商誉并做减值测试，最后核对少数股东权益、少数股东损益与合并净利润的勾稽。',
      '常见错误是只抵销当年内部交易而忽略连续编制时的期初未分配利润调整，或对商誉计提摊销。纠正方法是连续编报要先调期初数再处理本期交易；商誉只做减值测试，不摊销。',
      ['内部存货交易可举例。母公司向子公司销售商品成本80万元、售价100万元，子公司当年对外销售60%，剩余40%形成期末存货。合并层面应抵销营业收入100万元与营业成本100万元，同时抵销期末存货中未实现利润8万元，即借记营业成本8万元、贷记存货8万元。次年子公司将剩余存货对外销售，则期初未实现利润在本期实现，应借记期初未分配利润8万元、贷记营业成本8万元。连续编报的关键是区分已实现与未实现部分。', '商誉减值可举例。母公司支付1000万元取得子公司80%股权，购买日子公司可辨认净资产公允价值为1000万元，母公司享有份额800万元，商誉200万元。第一年末子公司整体可收回金额为900万元，包含商誉的资产组账面价值为1200万元，减值300万元。先冲减商誉200万元，剩余100万元按比例分摊至其他资产。合并报表中商誉降至零，减值损失计入当期损益，且以后不得转回。']
    ],
    ['外币折算', '本章区分外币交易与外币报表折算，解决汇率选择、汇兑差额去向与折算差额列示。',
      ['外币交易初始确认采用交易日即期汇率，也可采用近似汇率，但汇率波动大时不得使用近似汇率。', '期末货币性项目按资产负债表日即期汇率折算，差额计入当期损益，通常列作财务费用中的汇兑差额。', '非货币性项目按历史成本计量不调整汇率；以公允价值计量的非货币性项目按公允价值确定日汇率折算，差额计入公允价值变动损益或其他综合收益。', '外币财务报表折算中，资产与负债按资产负债表日即期汇率折算，所有者权益除未分配利润外按发生日汇率折算。', '利润表收入与费用按交易发生日汇率或近似汇率折算，折算差额计入其他综合收益。', '处置境外经营时，与该境外经营相关的外币报表折算差额应转入处置当期损益。'],
      '先区分交易是货币性还是非货币性项目，再确定期末汇率与差额去向；报表折算按资产负债、损益、权益分别选汇率，最后把折算差额计入其他综合收益。',
      '常见错误是给所有外币项目都调汇，或把报表折算差额计入当期损益。纠正方法是历史成本非货币性项目不调汇；报表折算差额属于其他综合收益，只有处置时才转入损益。',
      ['外币交易可举例。某企业12月1日赊购设备，价款10万美元，当日汇率7.0，折合70万元；12月31日汇率7.1，应付账款调整为71万元，差额1万元计入财务费用。若该设备以历史成本计量，则设备仍按70万元入账，不因汇率变动调整。若企业持有外币交易性金融资产，期末按公允价值与当日汇率折算，差额计入公允价值变动损益，而不是汇兑差额。', '报表折算可举例。某境外子公司资产1000万美元、负债400万美元、实收资本300万美元、未分配利润200万美元，年末汇率7.2，实收资本发生日汇率6.8。资产折算7200万元，负债2880万元，实收资本2040万元，未分配利润按折算后利润表计算为1400万元，折算差额为7200减2880减2040减1400等于880万元，计入其他综合收益。若处置该子公司，880万元转入投资收益。']
    ],
    ['租赁会计', '本章按新租赁准则确认使用权资产与租赁负债，解决租赁识别、计量与后续利息摊销。',
      ['租赁识别需存在已识别资产，且客户在使用期间有权主导资产使用并获得几乎全部经济利益。', '租赁期包括不可撤销期间、合理确定行使的续租选择权期间与合理确定不行使的终止选择权期间。', '租赁负债按租赁期开始日尚未支付的租赁付款额现值计量，折现率优先采用租赁内含利率，否则采用增量借款利率。', '使用权资产等于租赁负债加初始直接费用、预付租金、复原成本，减去租赁激励。', '后续计量中使用权资产计提折旧，租赁负债按实际利率法确认利息费用，支付租金冲减负债。', '短期租赁不超过十二个月与低价值资产租赁可简化处理，按直线法计入损益；售后租回先判断资产转让是否满足收入确认条件。'],
      '先判断是否存在租赁与租赁期，再确定租赁付款额与折现率计算租赁负债，随后确认使用权资产并按期计提折旧与利息，最后核对租赁负债余额与付款计划。',
      '常见错误是把所有租赁都费用化，或忽略续租选择权对租赁期的影响。纠正方法是除短期与低价值租赁外均需入表；租赁期要按合理确定行使的续租权判断，不能只看合同名义期限。',
      ['租赁负债可举例。某企业租入设备，每年末支付租金10万元，租期5年，增量借款利率5%，年金现值系数为4.3295，租赁负债为43.295万元。若期初支付租金10万元，则租赁负债为33.295万元，使用权资产再加预付租金。第一年利息为43.295乘5%等于2.165万元，支付10万元后负债降至35.46万元；使用权资产按5年直线折旧，每年8.659万元。租金支出被拆分为利息与本金偿还，不再全部计入当期费用。', '售后租回要分情形。企业将办公楼出售并租回，若转让满足收入确认条件，则按公允价值确认销售，使用权资产按保留使用权比例计量，利得仅确认转移给买方部分；若转让不满足收入确认条件，则作为融资处理，不确认销售利得。判断关键是买方是否取得控制权、回购价格是否公允、回购权性质。']
    ],
    ['金融工具进阶', '本章解决金融负债与权益工具的区分、金融资产分类、嵌入衍生工具与预期信用损失。',
      ['金融负债与权益工具区分的关键是是否存在无条件避免交付现金或其他金融资产的合同义务。', '固定换固定原则要求以固定数量自身权益工具交换固定金额现金或其他金融资产，才可作为权益工具。', '金融资产按业务模式与合同现金流量特征分为摊余成本、公允价值计量且变动计入其他综合收益、公允价值计量且变动计入当期损益三类。', '嵌入衍生工具与主合同不密切相关时应分拆，按公允价值单独计量，除非将整体指定为以公允价值计量且变动计入当期损益。', '预期信用损失三阶段：阶段一按十二个月预期信用损失计量，阶段二信用风险显著增加但未减值按整个存续期计量，阶段三已减值按整个存续期计量且利息收入按净额计算。', '金融资产转移需判断风险与报酬是否转移，未转移但保留控制的按继续涉入处理。'],
      '先做合同现金流与业务模式测试确定分类，再判断是否存在嵌入衍生工具与转移风险，期末按三阶段计提预期信用损失，最后核对公允价值变动去向。',
      '常见错误是把所有含回售条款的工具都归为权益，或对已减值金融资产仍按总额确认利息收入。纠正方法是回售条款可能构成交付现金义务，应归类为金融负债；阶段三应按摊余成本净额计算利息收入。',
      ['分类判断可举例。某企业持有债券，合同现金流仅为本金和利息，业务模式既收取合同现金流又准备出售，则应分类为公允价值计量且变动计入其他综合收益，公允价值变动计入其他综合收益，减值计入信用减值损失。若业务模式以交易为目的，则分类为公允价值计量且变动计入当期损益，公允价值变动直接计入损益。若债券含转股权且与主合同不密切相关，则需分拆嵌入衍生工具。', '预期信用损失三阶段可用数据说明。某银行贷款本金1000万元，阶段一按十二个月预期信用损失计提10万元；因借款人经营恶化，信用风险显著增加但未减值，转入阶段二，按整个存续期计提80万元；后借款人违约，转入阶段三，按整个存续期计提300万元。阶段三利息收入按摊余成本净额700万元乘实际利率计算，而不是按1000万元计算。']
    ],
    ['所得税会计', '本章处理会计与税法的暂时性差异，解决递延所得税资产与负债的确认、计量与列示。',
      ['资产计税基础为未来期间可税前扣除的金额，负债计税基础为账面价值减去未来期间可税前扣除的金额。', '账面价值大于计税基础形成应纳税暂时性差异，确认递延所得税负债；反之形成可抵扣暂时性差异，确认递延所得税资产。', '递延所得税按预期转回期间的适用税率计量，税率变动时调整递延所得税，影响所得税费用或相关权益项目。', '当期所得税等于应纳税所得额乘适用税率，所得税费用等于当期所得税加递延所得税。', '亏损弥补确认递延所得税资产应以很可能取得用来抵扣亏损的应纳税所得额为限，并披露未确认金额。', '商誉初始确认与既不影响会计利润也不影响应纳税所得额的非企业合并交易初始确认，不确认递延所得税。'],
      '先算资产与负债的账面价值与计税基础，确定差异类型，再按预期转回税率计算递延所得税，最后与当期所得税相加得出所得税费用并核对权益项目。',
      '常见错误是只按当期税率计算递延所得税，或对所有可抵扣差异都全额确认递延所得税资产。纠正方法是使用预期转回时税率；递延所得税资产需有足够应纳税所得额支持，否则只披露不确认。',
      ['暂时性差异可举例。某设备原值100万元，会计按5年折旧、每年20万元，税法按10年折旧、每年10万元。第一年末账面价值80万元、计税基础90万元，账面小于计税基础，形成可抵扣暂时性差异10万元，确认递延所得税资产2.5万元。第二年末账面60万元、计税基础80万元，差异20万元，递延所得税资产5万元，本期新增2.5万元。若税率由25%降为20%，应按20%重新计量递延所得税资产。', '亏损弥补可举例。某企业当年亏损500万元，预计未来五年应纳税所得额合计300万元，税率25%，则只能确认递延所得税资产75万元，剩余200万元亏损不确认但需披露。若次年企业盈利超预期，可补确认递延所得税资产并冲减所得税费用。判断关键是未来应纳税所得额的可靠性，不能仅凭管理层乐观预测。']
    ],
    ['股份支付与每股收益', '本章区分离结算与现金结算股份支付，并计算基本与稀释每股收益，是权益工具计量的难点。',
      ['权益结算股份支付在授予日按权益工具公允价值计量，等待期内按可行权数量最佳估计分摊计入成本费用与资本公积。', '现金结算股份支付按资产负债表日公允价值重新计量负债，等待期内计入成本费用与应付职工薪酬，可行权后公允价值变动计入公允价值变动损益。', '可行权条件分服务期限条件与业绩条件，市场条件在授予日公允价值中考虑，非市场条件影响可行权数量估计。', '基本每股收益等于归属于普通股股东的净利润除以发行在外普通股加权平均数，股票股利与拆股需追溯调整。', '稀释每股收益需考虑可转换债券、认股权证与股份期权等潜在普通股，计算增量股与增量收益。', '认股权证与股份期权的稀释性采用库藏股法，按行权价格与市价差额计算新增普通股数。'],
      '先判断结算方式与等待期，再估计可行权数量并分摊费用；计算每股收益时先算基本每股收益，再逐项测试潜在普通股是否具有稀释性并计算稀释每股收益。',
      '常见错误是权益结算股份支付在后续期间调整公允价值，或计算稀释每股收益时把潜在普通股全部加回而不考虑增量收益。纠正方法是权益结算只在授予日计量、后续不调；稀释计算要同时调整净利润与股数。',
      ['权益结算可举例。某公司授予100名管理人员每人1万股股票期权，授予日公允价值每股5元，等待期3年，预计三年内每年离职5%。第一年预计可行权数量为100乘95%乘1万等于95万股，费用为95万乘5除以3约158.33万元，借记管理费用、贷记资本公积其他资本公积。第二年调整离职率估计并累计计算，第三年行权时转入股本与股本溢价。', '稀释每股收益可举例。某公司净利润1000万元，发行在外普通股5000万股，另有可转换债券面值1000万元、利率4%、转换价每股10元，税率25%。基本每股收益为0.2元。债券转换可节省税后利息30万元，新增股数100万股，增量每股收益为0.3元，高于基本每股收益，具有反稀释性，不应计入稀释每股收益。若转换价降为每股5元，新增200万股，增量每股收益0.15元，低于0.2元，则应计入。']
    ],
    ['高财综合实训', '本章把合并、外币、租赁、金融工具与所得税串成一套合并报表，重点是工作底稿与勾稽。',
      ['工作底稿按个别报表调整、抵销分录、少数股东权益与合并数分栏，每笔分录都要有借贷平衡。', '个别报表调整包括统一会计政策、按购买日公允价值调整资产与负债、将长期股权投资由成本法调整为权益法。', '抵销分录覆盖权益抵销、内部存货与固定资产交易、内部债权债务与现金收支，连续编制时先调期初未分配利润。', '合并抵销会产生暂时性差异，需同步确认递延所得税，如内部交易未实现损益与资产公允价值调整。', '外币报表折算差额计入其他综合收益，少数股东应分担部分单独列示。', '附注应披露合并范围、子公司少数股东权益、商誉减值、外币折算与租赁负债到期分析。'],
      '先完成个别报表调整，再按权益、内部交易、债权债务顺序抵销，同步处理递延所得税，最后折算境外子公司并核对少数股东权益与合并净利润。',
      '常见错误是抵销重复或漏做，导致合并报表不平；或公允价值调整后忘记对应递延所得税。纠正方法是编制抵销分录清单逐项打勾，每笔调整都检查税会影响，最后用借贷平衡与勾稽关系双重验证。',
      ['抵销与递延所得税联动可举例。母公司向子公司销售存货，售价100万元、成本80万元，期末全部未对外销售。抵销分录借记营业收入100万元、贷记营业成本80万元与存货20万元，合并利润减少20万元，存货计税基础仍为100万元、账面价值80万元，形成可抵扣暂时性差异20万元，确认递延所得税资产5万元，借记递延所得税资产、贷记所得税费用。若忽略这一步，合并净利润与所得税费用都会失真。', '工作底稿勾稽可用公式检查。合并资产等于各主体资产合计加调整减抵销；合并负债同理；合并所有者权益等于母公司所有者权益加少数股东权益；合并净利润等于母公司净利润加子公司净利润份额减抵销未实现损益。任一项不符，应回到抵销分录与权益法调整查找。实训中建议先编抵销分录汇总表，再逐笔过人工作底稿，避免重复过账。']
    ]
  ],

  '审计学': [
    ['审计概述与职业道德', '本章界定审计的保证程度与三方关系，明确职业道德基本原则与独立性威胁的识别。',
      ['审计是对财务报表是否在所有重大方面按照适用财务报告框架公允反映发表意见的独立鉴证业务，提供合理保证而非绝对保证。', '三方关系为注册会计师、被审计单位管理层与预期使用者，管理层负责编制报表与内部控制，注册会计师负责发表意见。', '审计目标包括对报表整体是否存在重大错报发表意见，以及对与治理层沟通、报告等事项承担责任。', '职业道德基本原则为诚信、客观公正、专业胜任能力与应有的关注、保密、良好职业行为。', '独立性威胁包括自身利益、自我评价、过度推介、密切关系与外在压力，需通过防范措施消除或降至可接受水平。', '审计不能保证发现所有舞弊与差错，但应保持职业怀疑，识别和评估舞弊导致的重大错报风险。'],
      '先判断业务类型与保证程度，再识别独立性威胁并评价防范措施，随后按审计目标设计程序，最后区分管理层责任与注册会计师责任。',
      '常见错误是把合理保证等同于绝对保证，或认为审计是舞弊保证书。纠正方法是明确审计受重要性、抽样与估计不确定性限制；舞弊责任由管理层承担，注册会计师负责获取合理保证并报告。',
      ['独立性威胁可用场景说明。会计师事务所连续五年审计同一客户，项目合伙人同时为客户提供内部控制咨询，存在密切关系与自我评价威胁。防范措施包括轮换项目合伙人、分离咨询与审计团队、由项目质量复核人复核关键判断。若自我评价威胁无法消除，应拒绝承接或解除业务。独立性不仅是形式上的，还包括实质上的独立。', '审计责任与管理层责任不能互相替代。某公司管理层虚构销售导致报表重大错报，管理层对编制报表与防止舞弊负责；注册会计师若未按准则执行函证与截止测试，承担审计责任；若已按准则执行仍未能发现精心策划的舞弊，不能简单归责于注册会计师，但需证明程序充分适当并已在报告中沟通。']
    ],
    ['审计准则与法律责任', '本章明确审计准则的约束力与法律责任构成，解决执业过错与免责抗辩的判断。',
      ['审计准则体系包括一般原则、风险评估、风险应对、审计证据、审计报告与质量控制等，是执业的最低要求。', '职业怀疑要求对证据保持质疑态度，不轻信管理层声明，关注矛盾信息与异常关系。', '注册会计师法律责任分行政责任、民事责任与刑事责任，民事责任需具备过错、损失、因果关系与违法行为。', '遵守审计准则可作为抗辩依据，但不等于必然免责；若存在重大过失或舞弊参与，仍应承担责任。', '被审计单位舞弊不能完全转移审计责任，注册会计师应识别舞弊风险并设计应对程序。', '诉讼时效与举证责任影响责任承担，利害关系人需证明其信赖了存在重大错报的报表并遭受损失。'],
      '先看是否违反审计准则与职业道德，再判断是否存在过错、损失与因果关系，最后区分会计责任与审计责任并确定责任类型。',
      '常见错误是认为遵守准则就必然免责，或把客户舞弊作为完全抗辩。纠正方法是准则提供执业标准但不保证结果；若未保持职业怀疑或未执行必要程序，仍可能承担过失责任。',
      ['法律责任构成可用案例说明。投资者依据审计后的报表购买股票，后因公司虚构收入导致股价下跌。投资者需证明报表存在重大错报、其信赖报表并遭受损失；注册会计师若未执行函证、未关注异常毛利，存在过失，需承担相应民事赔偿责任。若注册会计师已执行充分程序且投资者并非基于报表决策，因果关系可能不成立。责任范围通常以损失为限，并按过错程度分担。', '职业怀疑的落实体现在细节。某公司年末收入激增、毛利率显著高于同业、应收账款周转天数延长，注册会计师应将其列为舞弊风险因素，执行收入截止测试、函证主要客户、检查期后回款与退货。若仅依赖管理层声明而不获取外部证据，属于程序不足。职业怀疑不是怀疑一切，而是对异常保持敏感并用证据验证。']
    ],
    ['审计计划与风险评估', '本章解决重要性确定、风险评估程序与进一步审计程序的设计，是风险导向审计的起点。',
      ['重要性分整体重要性、实际执行重要性与明显微小错报临界值，整体重要性通常按营业收入、资产总额或利润总额的一定比例确定。', '实际执行重要性低于整体重要性，用于设计程序以将未更正与未发现错报的合计影响降至可接受水平。', '风险评估程序包括询问管理层与相关人员、分析程序、观察与检查，目的是了解被审计单位及其环境与内部控制。', '风险分财务报表层次风险与认定层次风险，认定层次进一步分为固有风险与控制风险。', '了解被审计单位及其环境包括行业状况、监管环境、业务模式、会计政策、目标战略与财务业绩衡量。', '进一步审计程序包括控制测试与实质性程序，实质性程序是必须执行的程序，控制测试仅在拟信赖控制时实施。'],
      '先确定整体重要性与实际执行重要性，再通过询问、分析程序与观察识别风险，评估固有风险与控制风险，最后设计控制测试与实质性程序的性质、时间与范围。',
      '常见错误是把重要性定为一个固定比例而不考虑企业规模与报表使用者，或认为高风险领域才需要审计。纠正方法是重要性需运用职业判断并随情况更新；所有重大领域都要获取证据，高风险领域增加程序。',
      ['重要性可举例。某企业营业收入2亿元、资产总额1.5亿元、利润总额1000万元，注册会计师按营业收入0.5%确定整体重要性为100万元，按利润总额5%确定也为50万元，取较低者50万元作为整体重要性；实际执行重要性定为30万元，明显微小错报临界值定为2.5万元。若审计中发现未更正错报合计40万元，超过整体重要性，应考虑扩大程序或调整意见。', '风险评估要落到认定层次。某企业收入增长30%而行业增长5%，应收账款增速远高于收入，可能存在提前确认收入或虚构销售。注册会计师应识别收入的发生、截止与计价认定存在较高固有风险，设计函证、截止测试、期后回款检查等程序；同时评估管理层凌驾于控制之上的风险，测试会计分录与会计估计。']
    ],
    ['内部控制与测试', '本章解决内控了解、控制测试与实质性程序的关系，明确何时可以信赖内部控制。',
      ['内部控制五要素为控制环境、风险评估过程、控制活动、信息与沟通、监督，控制环境是基础。', '了解内部控制包括评价控制设计与确定控制是否得到执行，穿行测试是常用手段。', '控制测试用于验证控制在审计期间是否一贯有效运行，包括询问、观察、检查与重新执行。', '仅在拟信赖内部控制、预期控制有效运行且测试成本合理时实施控制测试，否则直接实施实质性程序。', '控制缺陷分设计缺陷与运行缺陷，重大缺陷需与治理层沟通并考虑对审计策略的影响。', '控制测试不能替代实质性程序，实质性程序是应对认定层次重大错报风险的必需程序。'],
      '先了解并记录内控流程与关键控制，判断是否拟信赖，再设计控制测试样本与期间，评价偏差率，最后根据测试结果调整实质性程序的范围。',
      '常见错误是把了解内控当作测试内控，或认为控制有效就可以减少实质性程序至零。纠正方法是了解仅判断设计与执行，测试才验证运行有效性；无论控制如何，实质性程序都必须执行。',
      ['控制测试可举例。某企业采购付款需经请购、审批、验收、发票核对与付款审批五个控制点。注册会计师拟信赖该控制，选取全年40笔样本，发现2笔缺少验收单，偏差率为5%。若可容忍偏差率为5%，则控制运行有效性存疑，应扩大样本或改为不信赖控制，增加应付账款完整性与截止测试的实质性程序。样本选择应覆盖全年，而不能只查年末。', '内控缺陷沟通要分级。一般缺陷可书面沟通给管理层；重要缺陷与重大缺陷需与治理层沟通。若发现管理层凌驾于控制之上，例如总经理可绕过审批直接付款，属于控制环境重大缺陷，应视为高风险，增加实质性程序并考虑对审计意见的影响。控制缺陷不等于报表错报，但会增加错报风险。']
    ],
    ['审计证据与抽样', '本章解决证据充分适当的判断与抽样风险控制，重点是函证、监盘与分析程序。',
      ['审计证据的充分性指数量，适当性指相关性与可靠性，外部独立来源、内部控制有效时生成的证据更可靠。', '函证用于获取第三方对账户余额或交易条款的确认，未回函应实施替代程序，不能直接视为无误。', '监盘用于获取存货存在与状况的证据，不能替代计价测试，注册会计师应制定监盘计划并现场观察。', '分析程序用于风险评估、实质性程序与总体复核，通过比较关系识别异常波动。', '抽样风险包括信赖过度风险、信赖不足风险、误受风险与误拒风险，非抽样风险源于程序设计与执行偏差。', '属性抽样用于测试控制偏差率，变量抽样用于估计金额错报，样本结果需评价可容忍偏差或错报。'],
      '先确定总体与抽样单元，选择统计或非统计方法，确定样本量与选取方式，执行程序并评价结果，最后根据偏差或错报决定是否扩大样本或调整程序。',
      '常见错误是函证未回函即认可余额，或监盘只点数不检查状况与权属。纠正方法是未回函必须执行替代程序；监盘要关注毁损、呆滞、代管与质押情况，并区分所有权。',
      ['函证与替代程序可举例。应收账款函证100户，回函70户，未回函30户。对未回函客户，注册会计师应检查期后收款、销售合同、发货单与发票，确认余额真实性；若仍无法获取充分证据，应考虑对报表的影响。回函不符的10户需逐户调查差异原因，不能简单接受管理层解释。函证控制应全程由注册会计师掌握，避免被审计单位拦截或干预。', '抽样评价可举例。控制测试中总体5000笔，样本60笔，发现3笔偏差，偏差率5%。若可容忍偏差率为4%，则不能信赖控制；若可容忍为6%，可初步信赖但需考虑偏差性质。实质性抽样中样本账面金额500万元、审定金额480万元，错报20万元，总体金额5000万元，采用比率法估计总体错报为200万元，超过可容忍错报，应扩大样本或调整审计策略。']
    ],
    ['业务循环审计', '本章按销售收款、采购付款、生产存货、筹资投资循环组织程序，重点是认定与截止测试。',
      ['销售收款循环重点为收入的发生、截止、准确性与应收账款的存在、计价，常用程序包括合同检查、函证、截止测试与期后回款。', '采购付款循环重点为应付账款的完整性与费用的截止，常用程序包括采购订单与验收单核对、发票检查、函证与期后付款检查。', '生产存货循环重点为存货的存在、计价与成本结转，常用程序包括监盘、计价测试、成本倒轧与分析程序。', '筹资投资循环重点为借款的完整性、抵押担保披露与投资的估值，常用程序包括函证、合同检查与公允价值评估。', '应付账款审计通常更关注低估，应收账款审计更关注高估，方向不同导致程序重点不同。', '截止测试通过检查资产负债表日前后若干天的发货单、验收单与发票，判断交易是否记入正确期间。'],
      '按循环识别认定层次风险，为每个重要认定配置程序，执行截止测试与函证，评价错报并汇总，最后与报表项目勾稽。',
      '常见错误是对应付账款只函证大额余额而忽略未入账负债，或收入截止测试只查发票不查发货与验收。纠正方法是应付账款结合期后付款与未入账负债检查；收入截止以控制权转移证据为核心，检查发货单、签收单与验收记录。',
      ['收入截止测试可举例。资产负债表日为12月31日，注册会计师选取12月最后10天与次年1月前10天的发货单，核对收入确认日期。若12月28日发货、次年1月3日客户签收，按控制权转移应在次年确认，若企业计入12月收入则属于提前确认，应提出调整。测试还应关注大额退货、寄售与代销，判断是否满足收入确认条件。', '应付账款完整性可举例。某企业年末应付账款余额2000万元，注册会计师选取主要供应商函证，并检查次年1月的付款记录与未入账发票。若发现次年1月支付上年12月已验收的材料款300万元未入账，应调增应付账款与存货或成本。完整性认定侧重低估，因此不能只依赖账面余额函证，还要从采购与验收记录反向追查。']
    ],
    ['审计报告', '本章解决意见类型的选择与报告要素，重点是范围限制与错报性质的区分。',
      ['审计意见分无保留意见、保留意见、否定意见与无法表示意见，后三者统称非无保留意见。', '错报重大但不广泛出具保留意见，重大且广泛出具否定意见；范围受限重大但不广泛出具保留意见，重大且广泛出具无法表示意见。', '关键审计事项段沟通注册会计师认为最重要的事项，包括识别原因与应对程序，不适用于无法表示意见的报告。', '持续经营存在重大不确定性时，应在报告中单独段落说明，并判断是否影响意见类型。', '审计报告要素包括标题、收件人、意见段、形成意见的基础、管理层与治理层责任、注册会计师责任、签字盖章与报告日期。', '其他信息部分应说明注册会计师对年报中非财务报表信息的责任与发现重大不一致时的处理。'],
      '先汇总未更正错报并与重要性比较，再判断是否存在范围限制，按重大与广泛两个维度选择意见类型，最后检查关键审计事项、持续经营与其他信息的披露。',
      '常见错误是把范围受限与错报混为一谈，或认为无法表示意见等于不发表任何内容。纠正方法是范围受限影响证据获取，错报影响报表本身；无法表示意见仍需说明原因与责任。',
      ['意见类型可举例。某企业存货占总资产40%，注册会计师因无法实施监盘且无替代程序，属于范围受限。若存货可能错报金额重大但不影响报表整体，出具保留意见；若存货错报可能影响多个报表项目且具有广泛性，出具无法表示意见。若企业故意少计负债5000万元，超过重要性且影响偿债能力判断，属于重大且广泛错报，出具否定意见。', '持续经营段落可举例。某企业连续三年亏损、流动负债远高于流动资产、主要借款即将到期且无展期安排，管理层仍按持续经营编制报表。注册会计师认为存在重大不确定性，应在报告中单独段落说明，并披露管理层应对计划；若认为持续经营假设不适当，则应出具否定意见；若无法获取充分证据，则考虑无法表示意见。']
    ],
    ['审计实训', '本章模拟完整审计流程，重点在底稿编制、程序执行与项目质量复核。',
      ['审计底稿应记录审计程序、获取证据、得出的结论与复核痕迹，做到索引清晰、可追溯。', '重点训练函证、监盘、截止测试与分析程序，每项程序要写清目的、步骤、样本与结论。', '审计调整建议应区分已更正与未更正错报，并汇总评价其对报表与意见的影响。', '项目质量复核由独立于项目组的复核人执行，重点关注重大判断、重大风险与意见类型。', '审计档案应在报告日后规定期限内归档，归档后不得随意修改，补充资料需记录理由。', '实训中常见问题包括底稿只抄数据不写结论、样本选择随意、复核意见未闭环。'],
      '按业务循环做一套底稿，先写程序表再执行，记录证据与结论，完成项目质量复核与归档，用复核清单逐项自检。',
      '常见错误是底稿越厚越好却没有结论，或复核发现问题不跟踪整改。纠正方法是每张底稿都要回答做了什么、发现什么、结论是什么；复核意见要登记、整改并再次复核，形成闭环。',
      ['函证底稿可示范。底稿应包含函证对象选取依据、函证地址与联系人核对、发函与回函控制、回函差异调节、未回函替代程序与结论。若回函金额与账面差异10万元，需查明是否为在途物资或未达账项，并取得支持性证据。底稿结论应明确该余额是否可确认，不能只贴回函复印件。', '项目质量复核要点包括：重大风险是否识别并应对、重要性与错报汇总是否合理、关键判断是否有依据、意见类型是否恰当、独立性是否受影响。复核人应在报告日前完成复核，重大分歧需记录解决过程。归档后若发现遗漏程序，应补充执行并记录原因，不能直接替换原底稿。']
    ]
  ],

  '财务管理': [
    ['财务管理导论', '本章界定财务管理的决策范围与目标，解释代理问题与金融市场的作用。',
      ['财务管理围绕投资、筹资、营运资金与股利分配四类决策，目标是企业价值最大化或股东财富最大化。', '投资决策决定资产配置与项目取舍，筹资决策决定资本结构与融资成本，股利决策决定利润留存与分配。', '利润最大化忽略风险、时间价值与投入资本，企业价值最大化更能反映长期与风险调整后的回报。', '代理问题源于所有权与经营权分离，股东与债权人、管理层之间可能存在利益冲突。', '解决代理问题的机制包括激励合同、董事会监督、外部接管、债权人保护条款与信息披露。', '金融市场提供融资、投资与风险管理场所，利率、汇率与市场有效性影响财务决策。'],
      '遇到财务问题先归类为投资、筹资、营运或分配决策，再确定目标与约束，最后用现金流、风险与资本成本三个维度评价方案。',
      '常见错误是用利润最大化替代价值最大化，或忽略代理冲突对决策的影响。纠正方法是把决策落到未来现金流、时间与风险；分析融资与投资时同时考虑股东与债权人利益。',
      ['四类决策可用一家制造企业说明。是否新建工厂属投资决策，需估算增量现金流并用净现值判断；选择银行贷款还是发行债券属筹资决策，需比较税后成本与控制权影响；存货与应收政策属营运资金决策，需平衡流动性与收益；是否分红或回购属分配决策，需考虑自由现金流与股东偏好。四类决策相互影响，不能孤立看。', '代理冲突可用案例说明。股东可能偏好高风险高回报项目，因为收益归股东、损失由债权人分担；债权人会在合同中加入限制分红、限制新增负债的条款。管理层可能追求规模与在职消费，股东通过股票期权与业绩考核加以约束。财务管理的任务不是消除冲突，而是设计机制使激励尽量一致。']
    ],
    ['时间价值与估值', '本章解决货币时间价值计算与债券股票估值，核心是现金流、折现率与期限的匹配。',
      ['复利终值等于现值乘一的加利率的n次方，复利现值是终值除以同一系数，利率与期数必须口径一致。', '普通年金现值系数为1减(1加i)的负n次方除以i，预付年金比普通年金多乘(1加i)。', '永续年金现值等于每期现金流除以折现率，增长永续年金现值为下期现金流除以折现率减增长率。', '债券价值等于利息年金现值加本金现值，折现率用市场同类债券的必要收益率。', '股票估值可采用股利折现模型，稳定增长时价值等于下期股利除以必要收益率减增长率。', '相对估值用市盈率、市净率与EV/EBITDA，需选择可比公司并调整差异。'],
      '先画现金流时间轴，确定每期现金流与折现率，再选对应公式计算现值，最后做敏感性分析检验利率与增长率假设。',
      '常见错误是年金与预付年金差一期，或折现率与现金流口径不一致。纠正方法是画时间轴确认首期时点；名义现金流用名义折现率，税后现金流用税后折现率。',
      ['债券估值可举例。面值1000元、票面利率5%、期限5年、每年付息一次，市场必要收益率6%。每年利息50元，年金现值系数为4.2124，本金现值系数为0.7473，债券价值为50乘4.2124加1000乘0.7473等于210.62加747.3等于957.92元，低于面值，属于折价债券。若必要收益率降为4%，价值升至1044.52元，属于溢价。', '股票估值可举例。某股票刚支付股利1元，预计股利年增长5%，必要收益率10%，则下期股利1.05元，价值为1.05除以(10%减5%)等于21元。若股价为25元，高估；若股价为18元，低估。增长率接近折现率时估值对假设极度敏感，因此要检验增长率的可持续性，不能把历史高增长永久外推。']
    ],
    ['风险与收益', '本章解决风险计量与必要收益率确定，核心是组合分散与资本资产定价模型。',
      ['期望收益率是各情景收益率按概率加权平均，方差是偏离期望的平方按概率加权，标准差为方差平方根。', '变异系数等于标准差除以期望收益率，用于比较不同规模项目的相对风险。', '组合期望收益是各资产期望收益按权重加权，组合风险取决于协方差与相关系数，不完全相关可分散风险。', '系统风险不可通过组合分散，用β衡量；非系统风险可通过分散消除，市场不给予额外补偿。', '资本资产定价模型为必要收益率等于无风险利率加β乘市场风险溢价。', '证券市场线描述期望收益与β的线性关系，β大于1的资产要求更高回报。'],
      '先估计情景概率与收益率计算期望与标准差，再计算组合协方差与β，最后用资本资产定价模型确定必要收益率并与预期收益比较。',
      '常见错误是认为高风险必然高收益，或把标准差最大等同于系统风险最大。纠正方法是高风险只要求高期望收益，不代表一定实现；标准差含非系统风险，β才衡量系统风险。',
      ['组合分散可举例。两只股票期望收益均为10%，标准差均为20%，相关系数为0时等权组合标准差为14.14%，低于单只股票；相关系数为1时组合标准差仍为20%，无分散效果；相关系数为负1时可完全消除风险。现实中相关系数多在0到1之间，分散能降低但不能消除风险。', '资本资产定价模型可举例。无风险利率3%，市场风险溢价6%，某股票β为1.2，必要收益率为3%加1.2乘6%等于10.2%。若该股票预期收益为12%，高于必要收益，值得投资；若预期收益为9%，则不值得。β为0.8的防御型股票必要收益率为7.8%，在市场下跌时相对抗跌。']
    ],
    ['资本预算', '本章用净现值等指标评价长期项目，核心是增量现金流估算与折现率选择。',
      ['净现值等于未来现金流现值减初始投资，净现值大于零项目可行，互斥项目优先选择净现值最大者。', '内部收益率是使净现值为零的折现率，内部收益率大于资本成本可行，但互斥项目可能与净现值结论冲突。', '回收期衡量收回初始投资所需时间，未考虑时间价值与回收期后现金流，只能作为辅助指标。', '获利指数等于未来现金流现值除以初始投资，适用于资本限额下的项目排序。', '增量现金流应包括营业收入、付现成本、折旧税盾、营运资金与残值，不包括沉没成本与融资成本。', '敏感性分析、情景分析与实物期权分析用于处理不确定性，实物期权包括扩张、放弃与延迟期权。'],
      '先估算增量现金流并确定折现率，再计算净现值与内部收益率，互斥项目以净现值为准，最后做敏感性分析并考虑实物期权价值。',
      '常见错误是把折旧当作现金流出，或把融资利息计入项目现金流。纠正方法是折旧本身不是现金流，只有折旧抵税才是；融资成本已体现在折现率中，不能重复扣除。',
      ['净现值可举例。项目初始投资1000万元，预计5年每年营业收入600万元、付现成本350万元，折旧200万元，税率25%，折现率10%。年税后现金流为(600减350减200)乘75%加200等于237.5万元，5年年金现值系数3.7908，现值为900.3万元，净现值为负99.7万元，项目不可行。若营业收入提高至650万元，年现金流为275万元，现值1042.5万元，净现值为正42.5万元。', '互斥项目冲突可举例。项目A初始投资100万元，内部收益率20%，净现值30万元；项目B初始投资500万元，内部收益率15%，净现值80万元。若资本充足，应选净现值更大的B；若资本限额100万元，则只能选A。内部收益率假设现金流按内部收益率再投资，净现值假设按资本成本再投资，后者更合理。']
    ],
    ['资本成本与结构', '本章解决加权平均资本成本计算与资本结构选择，核心是税盾、破产成本与融资优序。',
      ['债务成本应为税后成本，等于税前利率乘一减税率；权益成本可用资本资产定价模型或股利增长模型估算。', '加权平均资本成本等于债务权重乘税后债务成本加权益权重乘权益成本，权重优先使用市场价值。', '无税MM理论认为资本结构不影响企业价值，有税MM理论认为负债利息税盾增加企业价值。', '权衡理论认为最优结构在税盾收益与财务困境成本之间平衡，过度负债会增加破产与代理成本。', '优序融资理论认为企业优先使用内部留存，其次债务，最后股权，因信息不对称与发行成本。', '杠杆提高会增加股东风险与必要收益率，但税盾降低综合成本，需计算不同结构下的加权成本与价值。'],
      '先估算各来源资本成本，再按市场价值权重计算加权平均资本成本，比较不同负债水平下的成本与价值，最后结合行业、现金流稳定性与契约约束选择结构。',
      '常见错误是使用账面权重或税前债务成本，或认为负债越多越好。纠正方法是权重尽量用市值，债务成本必须税后；负债超过临界点后财务困境成本上升，加权成本反而提高。',
      ['加权平均资本成本可举例。某企业债务市值4000万元、税前利率6%、税率25%，权益市值6000万元、权益成本12%。税后债务成本4.5%，权重分别为40%与60%，加权成本为40%乘4.5%加60%乘12%等于1.8%加7.2%等于9%。若企业将负债提高到6000万元、权益降至4000万元，债务成本升至7%、权益成本升至14%，加权成本为60%乘5.25%加40%乘14%等于3.15%加5.6%等于8.75%，略降；若债务成本升至9%、权益成本升至18%，加权成本为60%乘6.75%加40%乘18%等于11.25%，反而上升。', '优序融资可用案例说明。某企业需要新项目资金，内部留存充足时优先使用留存，避免发行费用与信号效应；留存不足时发行债券，因债务对信息不对称敏感度较低；最后才发行股票，因投资者可能将增发解读为股价高估。现实中企业常保留财务弹性，避免在不利时机被迫融资。']
    ],
    ['营运资金与股利', '本章解决流动性管理与利润分配，核心是现金周期、最佳现金持有与股利政策选择。',
      ['现金周期等于存货周转天数加应收账款周转天数减应付账款周转天数，周期越短占用资金越少。', '最佳现金持有量在持有成本与短缺成本之间权衡，持有成本包括机会成本与管理成本，短缺成本包括交易与信誉损失。', '存货经济订货批量等于根号下二乘每次订货成本乘年需求量除以单位储存成本。', '信用政策包括信用标准、信用条件与收账政策，放宽信用可增加销售但增加坏账与资金占用。', '股利政策有剩余股利、固定股利、固定支付率与低正常加额外股利，选择取决于现金流稳定性与投资机会。', '股票回购与现金股利都可向股东返还现金，回购可提高每股收益但可能增加财务风险。'],
      '先算现金周期定位占用环节，再分别优化存货、应收与应付，评估信用政策变化对增量收益与成本的影响，最后结合自由现金流与投资计划选择股利政策。',
      '常见错误是认为流动比率越高越好，或只看股利收益率不看可持续性。纠正方法是高流动比率可能意味资金闲置或存货积压；股利应来自自由现金流，靠举债分红不可持续。',
      ['现金周期可举例。某企业存货周转天数60天、应收账款周转天数45天、应付账款周转天数30天，现金周期为75天。若将应收账期缩短至30天，现金周期降至60天，释放资金约相当于15天销售额。若供应商将账期延长至45天，现金周期进一步降至45天。优化顺序应优先缩短存货与应收，因其可控性较强；延长应付需考虑供应商关系与折扣成本。', '股利政策可举例。某企业净利润1000万元，下年计划投资800万元，目标资本结构为负债40%、权益60%，则投资所需权益资金480万元，剩余股利为520万元。若企业采用固定股利每股0.5元、共500万股，需支付250万元，剩余750万元可用于投资，不足部分举债。选择哪种政策取决于投资机会、现金流稳定性与股东偏好。']
    ],
    ['财务分析与预测', '本章用比率与杜邦体系诊断企业，并用销售百分比法预测外部融资需求。',
      ['偿债能力指标包括流动比率、速动比率、资产负债率与利息保障倍数，需结合行业与现金流判断。', '营运能力指标包括应收账款周转率、存货周转率与总资产周转率，反映资产使用效率。', '盈利能力指标包括毛利率、净利率、总资产净利率与净资产收益率，分母优先使用平均余额。', '杜邦分析将净资产收益率分解为净利率乘总资产周转率乘权益乘数，分别对应盈利、效率与杠杆。', '销售百分比法假设经营资产与经营负债随销售同比例变动，外部融资需求等于销售增长所需资金减留存收益增加。', '可持续增长率等于净资产收益率乘留存率除以一减净资产收益率乘留存率，反映不增发新股时的最大增长。'],
      '先做趋势与结构分析，再算比率并与同业比较，用杜邦分解定位驱动因素，最后用销售百分比法预测融资需求并做情景分析。',
      '常见错误是比率口径不一致或忽略期末余额的季节性，或把可持续增长率当作实际增长率目标。纠正方法是统一分子分母口径并使用平均余额；可持续增长率是平衡增长参考，实际增长还受市场与产能约束。',
      ['外部融资需求可举例。某企业今年销售收入1000万元，经营资产占销售60%、经营负债占销售20%，销售净利率10%、留存率50%，明年销售增长20%。经营资产增加为1000乘20%乘60%等于120万元，经营负债增加为1000乘20%乘20%等于40万元，资金需求80万元；留存收益增加为1200乘10%乘50%等于60万元，外部融资需求20万元。若增长30%，外部融资需求将进一步扩大。', '可持续增长率可举例。某企业净资产收益率15%、留存率60%，可持续增长率为15%乘60%除以(1减15%乘60%)等于9%除以91%等于9.89%。若企业实际增长20%，则需外部融资或提高留存率、周转率与杠杆。提高杠杆可短期提升可持续增长率，但会增加财务风险，不能无限使用。']
    ],
    ['财务案例', '本章整合估值、资本预算、资本结构与营运资金，训练从假设到结论的完整分析。',
      ['案例框架为背景与问题、数据与假设、方案比较、结论与建议，假设要写明依据与敏感性。', '估值案例需预测自由现金流、确定折现率与终值，终值增长假设不应高于长期经济增长率。', '资本预算案例需区分增量现金流与沉没成本，考虑营运资金投入与回收、残值与税盾。', '资本结构案例需比较不同负债水平下的加权成本、利息保障倍数与契约约束。', '结论要落到可执行建议，包括融资安排、投资节奏与风险控制措施。', '敏感性分析应识别关键变量，给出乐观、基准、悲观三种情景下的结果区间。'],
      '先列关键假设与数据来源，再建模计算核心指标，比较方案并做敏感性分析，最后给出优先级、实施步骤与风险应对。',
      '常见错误是套公式忽略假设，或只用单一情景得出结论。纠正方法是说明假设的合理性并检验关键变量；结论应给出区间与触发条件，而非单点数字。',
      ['估值案例可演示。某企业基期自由现金流5000万元，预计未来5年增长8%，之后永续增长3%，加权平均资本成本9%。第5年现金流为5000乘1.08的5次方等于7346.6万元，终值为7346.6乘1.03除以(9%减3%)等于126,116万元，折现后终值现值约81,980万元，加上预测期现金流现值约25,000万元，企业价值约107,000万元。若永续增长率降为2%，价值下降约15%。', '方案比较可举例。某企业有A、B两个扩张方案，A投资1亿元、净现值2000万元、回收期4年；B投资1.5亿元、净现值2600万元、回收期6年。资本充足时选B，因净现值更大；若资金紧张或风险承受能力低，可选A。还需考虑战略协同、产能消化与竞争反应，不能只看净现值单一指标。']
    ]
  ],

  '毕业论文': [
    ['选题与文献', '本章解决选题从宽泛兴趣到可操作研究问题的转化，以及文献检索与综述的基本方法。',
      ['好选题需同时满足问题真实、数据可得、范围可控、有一定理论与现实价值四个条件。', '研究问题应具体到变量、对象、时间与情境，避免浅谈、对策研究这类无法验证的题目。', '文献检索常用中国知网、万方、谷歌学术与SSRN，先读综述与高被引文献，再追前沿。', '文献综述按主题而非按作者罗列，要归纳共识、分歧与研究缺口。', '开题报告应写清研究问题、文献基础、研究方法、数据来源、预期贡献与进度安排。', '选题调整要及早在文献与数据可行性之间取得平衡，不要等到写作阶段才发现无数据。'],
      '先列三到五个兴趣方向，再对每个方向做一轮文献检索与数据可得性核查，用问题、数据、价值三问筛选，最后把选题缩到一句话并写开题提纲。',
      '常见错误是题目过大、综述变成摘要堆砌、研究方法与研究问题不匹配。纠正方法是把题目限定到具体行业与期间，综述按主题归纳并指出缺口，方法选择以能回答问题为准。',
      ['选题可用漏斗法：先确定学科领域，再聚焦到细分主题，再限定对象与期间，最后形成可检验的问题。例如从企业财务风险缩到房地产企业财务风险，再缩到某类房企在三条红线政策后的融资约束与财务风险，问题变成政策冲击如何影响融资成本与投资行为。范围越小，数据越容易获取，论证也越深入。', '文献综述要建立矩阵：横轴是研究主题或变量，纵轴是作者与年份，格子里写样本、方法、结论与局限。读完二十篇核心文献后，归纳三类内容：已形成的共识、仍存在的分歧、尚未回答的问题。研究缺口可能来自新情境、新数据、新方法或变量间关系未检验。综述结尾要自然引出本文问题，而不是简单说研究较少。']
    ],
    ['研究方法与数据', '本章解决研究设计与数据处理的匹配问题，重点是变量定义、识别策略与稳健性检验。',
      ['研究设计先确定是实证、案例、问卷还是实验，方法服务于问题而不是反过来。', '实证研究需明确因变量、自变量、控制变量、模型设定与识别策略，避免遗漏变量与内生性。', '案例研究选典型样本，用多来源证据三角验证，区分事实、解释与推论。', '问卷设计避免引导性题项，先做预调研检验信度与效度，再正式发放。', '数据清洗包括缺失值、异常值、重复值与口径统一，需记录处理规则。', '稳健性检验可用替换变量、改变样本、增加控制变量、工具变量或倾向得分匹配。'],
      '先判断问题类型，再选方法与数据，写出变量定义表与模型，做描述统计与相关性分析，最后回归并做稳健性检验。',
      '常见错误是方法炫技不解决问题、样本选择偏差、把相关当因果。纠正方法是让方法匹配问题，说明样本边界，使用识别策略并谨慎表述因果。',
      ['内生性来源可举例。研究广告投入对销售的影响，若高销售企业更有钱投广告，存在反向因果；若遗漏品牌力，存在遗漏变量偏差。可用工具变量、双重差分、断点回归或倾向得分匹配缓解。工具变量需满足相关性与外生性，双重差分需满足平行趋势。不能只跑普通最小二乘就宣称因果。', '案例研究要保证证据链。以某企业财务造假为例，资料包括年报、审计报告、监管处罚、媒体报道与访谈。先按时间线还原事实，再用理论解释动因与机会，最后提出可检验的推论。三角验证要求同一结论至少有两个独立来源支持；若只有单一来源，应标注为待验证假设。']
    ],
    ['写作与规范', '本章解决论文结构、论证与学术规范，确保结论有证据支持且引用可追溯。',
      ['论文结构一般为引言、文献综述、研究设计、结果分析、讨论与结论，章节之间要有逻辑衔接。', '引言写清背景、问题、方法、贡献与结构，避免写成政策口号。', '论证要有证据，数据、案例与文献要注明来源，图表要自明并有正文解释。', '引用格式全篇统一，直接引用与间接引用都要标注，避免抄袭与自我抄袭。', '摘要包含目的、方法、主要发现与结论，关键词三到五个，正文不出现未定义缩写。', '查重前先做引文规范与改写，降重不能改变原意，也不能牺牲学术规范。'],
      '先写提纲再填内容，每章先写主题句再展开证据，完成后统一格式、核对引文、检查图表编号与查重报告。',
      '常见错误是结论超出数据支持范围、参考文献格式混乱、图表无来源。纠正方法是结论只回答研究问题，格式按学校模板统一，图表注明数据来源与计算口径。',
      ['结论与讨论要分开。结果部分只报告发现了什么，如回归系数、显著性与经济意义；讨论部分解释为什么、与已有文献一致或矛盾、可能的机制与边界条件。结论部分回答研究问题并提出建议，建议要具体可执行，不能写成加强管理、提高认识这类空话。', '学术规范红线包括抄袭、篡改数据、伪造引用与代写。引用他人观点必须标注，数据来源要可追溯，问卷与访谈需知情同意与匿名处理。查重报告重复率高不一定是抄袭，可能是方法描述与公式；但连续大段复制必须改写并标注。降重时保留原意与引用，不能通过替换同义词掩盖抄袭。']
    ],
    ['答辩', '本章解决答辩陈述、问题应答与意见修改，重点是把研究逻辑讲清楚而不是念论文。',
      ['陈述结构为为什么做、怎么做、发现什么、有什么贡献，控制在八到十分钟。', 'PPT少字多图，每页一个核心观点，避免把论文段落直接搬上屏幕。', '高频问题包括创新点、样本代表性、变量度量、内生性、结论稳健性与实践意义。', '回答先结论后理由，遇到不确定的问题承认边界并说明可改进方向。', '时间控制要预留提问与切换设备的时间，提前演练并准备备份文件。', '答辩后按评审意见逐条修改，形成修改说明并与导师确认。'],
      '按四段式写讲稿并计时演练，准备十个高频问题的答案，答辩时先复述问题再回答，最后记录意见并逐条落实。',
      '常见失分点是念稿、超时、答非所问与PPT信息过载。纠正方法是脱稿讲清逻辑、提前计时演练、回答紧扣问题，每页只留关键词与图表。',
      ['创新点可以来自问题、数据、方法或情境。问题创新是研究别人没问过的问题；数据创新是使用独特样本或手工收集数据；方法创新是采用更适合的识别策略；情境创新是把成熟理论放到新制度环境检验。创新不一定宏大，但要能说清与已有研究的区别，不能把别人没研究过当作唯一理由。', '答辩问答可用三步：先给结论，再给依据，最后说边界。例如被问样本是否具有代表性，可回答样本覆盖某行业三年数据，结论适用于该细分行业，不能推广到全部企业；再说明样本选择依据与局限。遇到不会的问题，承认尚未深入并说明后续可如何检验，比强行编造更可靠。']
    ]
  ],

  '专业实习': [
    ['岗位与角色', '本章解决实习初期如何快速理解岗位职责与协作关系，避免因接口不清造成返工。',
      ['岗位说明书明确职责、权限、考核指标与汇报关系，入职第一周应主动索取并阅读。', '协作图画出上游、下游、平行部门与外部对接人，标清交付物与时限。', '保密与合规要求包括客户信息、财务数据、内幕信息与个人信息保护。', '职业形象包括守时、邮件规范、会议记录与及时反馈。', '主动反馈应带着方案提问，说明已尝试什么、卡在哪里、需要什么支持。', '实习目标要可衡量，如独立完成某类凭证、跟完一个月结、掌握某系统模块。'],
      '入职第一周画岗位协作图并列出一个月学习清单，每周与导师复盘一次，月末对照目标检查完成度。',
      '常见错误是不问清楚就上手、越权处理、把问题直接抛给导师。纠正方法是先读制度与历史资料，涉及权限先请示，提问时附上自己的判断与备选方案。',
      ['岗位协作图可这样画：中心写自己的岗位，左侧列上游提供数据的岗位，如采购、销售、仓库；右侧列下游使用成果的岗位，如总账、税务、管理层；上方列审批与指导关系；下方列外部对接，如银行、税务、审计。每条连线标注交付物、频率与时限。画完会发现很多返工来自接口不清，而不是个人能力。', '保密合规不是口号。实习中可能接触工资、客户名单、未公开财报与投标底价，这些不得拍照、外传或在社交平台讨论。使用公司系统要遵守权限，不得借用他人工号；离职时按要求归还资料与设备。发现违规应报告导师或合规部门，不能因为自己是实习生就免责。']
    ],
    ['核算与报税', '本章解决把凭证、账簿、申报串成完整月结周期，训练独立完成基础核算与纳税申报。',
      ['跟完一个完整月结周期，从凭证审核、记账、计提、结转、对账到出表。', '发票环节包括开具、认证、红冲与作废，注意税率、品目与购买方信息准确。', '纳税申报包括增值税、附加税、企业所得税预缴与个人所得税，申报表要与账面数据核对。', '建立业务与分录对照表，记录常见业务的科目、附件与税务处理。', '银行对账要编制余额调节表，查明未达账项并跟踪单据到达。', '凭证归档按日期与凭证号装订，附件齐全，电子档案按权限保存。'],
      '每月按清单推进：收集单据、审核凭证、记账、计提折旧与税费、结转成本与损益、对账、出表、申报，每步留底稿并复核。',
      '常见错误是照抄旧凭证不理解准则依据、申报表与账面不一致、发票信息错误导致退回。纠正方法是每笔分录写依据，申报前做账表核对，开票前双人复核购买方与税率。',
      ['月结清单可按时间排：月初核对银行与现金，处理上月未达账项；月中审核费用与采购凭证，计提工资社保；月末计提折旧摊销、结转制造费用与完工成本、结转销售成本、计提税费、结转损益、出表。每项都有责任人与截止日，延迟一项会影响后续。实习生应先跟一遍再独立做。', '发票错误处理要区分情形。购买方信息错误或税率错误，当月可作废重开；跨月需红冲后重开。红字发票需按规定开具红字信息表，不能随意冲减销售额。认证抵扣要在规定期限内完成，逾期可能影响进项抵扣。实习中遇到不确定的发票，先查制度或问税务岗，不要自行处理。']
    ],
    ['审计与内控实习', '本章解决审计实习中的程序执行与底稿编制，重点是函证、监盘、截止测试与复核。',
      ['函证要控制发函与回函全过程，核对地址与联系人，未回函执行替代程序。', '监盘要制定计划、现场观察、记录盘点结果，关注毁损、呆滞与权属。', '截止测试检查资产负债表日前后交易，判断是否记入正确期间。', '底稿要写清目的、程序、样本、证据与结论，索引清晰可追溯。', '内控测试与实质性程序不同，控制测试验证运行有效性，实质性程序获取认定层次证据。', '项目质量复核关注重大判断、重大风险与意见类型，复核意见要闭环。'],
      '每做一项程序先写目的与样本，再执行并留存证据，最后写结论；底稿完成后按复核清单自检并请导师复核。',
      '常见错误是只填表不理解为什么做、函证由客户代发、监盘只点数不看状况。纠正方法是先理解认定与风险，控制函证全过程，监盘关注权属与减值迹象。',
      ['函证控制可举例。注册会计师应自行核对被函证单位的名称、地址与联系人，避免被审计单位拦截；发函与回函应由项目组直接控制，回函直接寄至事务所。若回函率低，应对未回函项目实施替代程序，如检查合同、发货单、期后收款。由客户代发或代收的函证，可靠性显著降低。', '监盘不是简单数数。某仓库存货堆放混乱，盘点表由仓库人员填写，注册会计师应观察盘点过程、抽盘部分项目、检查存货状况与标签，并关注是否有代管、质押或已销售未发货的存货。对毁损呆滞存货，要评估跌价准备是否充分。监盘获取存在证据，计价仍需独立测试。']
    ],
    ['实习复盘', '本章解决把实习经历转化为可迁移能力与求职素材，重点是用证据复盘而非流水账。',
      ['用STAR结构写案例：情境、任务、行动、结果，结果尽量量化。', '总结业务知识、工具技能与协作能力三条成长线，避免只写流水账。', '请导师与同事给具体反馈，记录改进行动与时间点。', '把实习经历转化为简历素材与面试故事，突出可迁移能力。', '复盘要诚实面对失误，分析原因并写出下次做法。', '职业规划可比较企业财务、事务所、银行与公务员的方向，结合兴趣与能力。'],
      '每周写一页复盘，月末整理三个STAR案例，离岗前请导师做一次正式反馈，形成改进清单并跟踪落实情况。',
      '常见错误是只写做了什么没有反思，或把团队成果全归个人。纠正方法是写清自己的行动与贡献，用数据说明结果，同时说明团队协作与不足。',
      ['STAR案例要具体。情境：月结时发现银行对账单与账面差20万元；任务：在两小时内查明原因；行动：编制余额调节表、逐笔核对未达账项、联系银行取得回单；结果：确认是未达账项并完成调节，月结按时完成。案例要突出个人行动与可迁移能力，而不是公司背景。', '反馈要主动获取。离岗前可问导师三个问题：我做得最好的三件事是什么，最需要改进的两点是什么，如果继续实习应先补哪项能力。把回答转成具体行动，如学习表格透视表、练习写审计说明、提高英文邮件能力。复盘不是自我批评，而是把经验变成下一次的方法。']
    ]
  ],

  '考研与求职': [
    ['考研方向', '本章解决学硕与专硕的选择、院校筛选与备考时间线安排，重点是核对招生信息并让目标与自身实力匹配。',
      ['学硕偏学术、专硕偏应用，会计学硕与会计专硕在考试科目、学费与培养方式上不同。', '院校选择看报录比、复试线、专业课难度、地域与就业资源，不能只看排名。', '招生简章与专业目录是权威信息，需核对考试科目、参考书与是否接受跨考。', '时间线一般分为基础、强化、冲刺与复试四阶段，需倒排计划。', '信息渠道包括研招网、院校研究生院、学长学姐与历年真题。', '目标设定要留有余地，准备一个冲刺院校与一个稳妥院校。'],
      '用兴趣、实力与就业三维筛选院校，列出三到五所并逐项核对报录比、复试线与参考书，再倒排全年复习计划，每月检查完成进度。同时准备一个冲刺院校与一个稳妥院校，避免单点风险。',
      '常见错误是只看排名不看报录比与专业课难度，或频繁换院校导致复习断裂。纠正方法是收集近三年数据，确定后至少坚持一个阶段再评估。',
      ['院校筛选可做表格：列学校、专业、近三年报录比、复试线、专业课科目与参考书、学费、地域与就业。报录比低不一定难，可能招生少；复试线低可能专业课压分。最好找到拟录取名单，观察分数分布与调剂情况。信息越具体，决策越可靠。', '时间线可这样排：三月到六月打基础，完成英语单词与数学或专业课第一轮；七月到九月强化，刷题与建立框架；十月到十一月真题与背诵；十二月冲刺与模考；次年二月准备复试。每月设里程碑，避免只看总时长不看完成度。']
    ],
    ['专业课复习', '本章解决三轮复习的节奏与输出化训练，重点是用真题反推重点并建立可复述的知识框架，避免盲目刷题。',
      ['三轮复习法：第一轮搭框架，第二轮刷真题与专题，第三轮默写与输出。', '框架图按章、节、知识点三级整理，标注公式、分录与易混概念。', '真题要研究题型、分值分布与命题风格，按考点反推重点。', '背诵要输出化，用默写、口述与做题检验，而不是反复阅读。', '错题本按知识点归类，记录错因、正确思路与同类题。', '关注会计准则与税法变化，新版教材与准则解释优先。'],
      '先通读教材建框架，再按真题标注高频考点，最后用默写与限时做题检验，错题每周复盘一次。',
      '常见错误是只背不理解、资料贪多、忽略真题风格。纠正方法是每章用自己的话复述并做例题，资料以教材与真题为主，按题型分类训练。',
      ['框架图可这样建：以中级财务会计为例，一级是资产、负债、权益、收入、报表；二级是货币资金、存货、固定资产、金融资产等；三级写确认条件、计量方法、分录与披露。每个知识点旁标注真题年份与题型。框架图不是抄目录，而是把知识之间的关系画出来，如存货跌价准备如何影响利润与资产。', '输出化复习可用费曼法。学完一章后合上书，用空白纸写出概念、公式、分录与例子，再对照教材补漏。能讲给别人听且经得起追问，才算掌握。做题时先写思路再写答案，错题要区分是概念不清、计算错误还是审题失误，不同错因用不同纠正方法。']
    ],
    ['求职方向', '本章解决会计就业方向的选择与简历准备，重点是把岗位要求转成可展示的能力证据。',
      ['企业财务岗位分核算、税务、资金、成本、财务分析与业务财务，发展路径不同。', '会计师事务所看重注册会计师通过科目、实习经历与抗压能力，晋升路径相对清晰。', '银行、券商与基金岗位差异大，需关注业务条线与证书要求。', '公务员与事业单位财务岗位稳定，考试内容与招录时间需提前了解。', '简历用数字量化成果，按岗位要求调整关键词与项目顺序。', '秋招与春招节点要提前准备，实习转正与内推是重要渠道。'],
      '先列三到五个目标岗位，拆解岗位要求，再按岗位改简历并准备对应案例，最后跟踪投递进度与面试反馈。',
      '常见错误是一份简历投所有岗位、经历描述只有职责没有成果。纠正方法是按岗位定制关键词，用动作加数据加结果描述经历，如将月结时间从五天缩短到三天。',
      ['岗位差异可举例。核算岗重凭证、月结与报表，要求细致与准则熟练；税务岗重申报、发票与税务筹划，要求政策敏感；财务分析岗重预算、差异分析与业务沟通，要求建模与表达；事务所审计岗重程序、底稿与抗压，要求快速学习与出差适应。选择前先了解日常工作节奏，而不是只看薪资。', '简历可用情境加行动加结果。把负责应收账款管理改为管理三百家客户应收账款，建立账龄跟踪表，将逾期率从百分之十五降至百分之八。数字要真实可解释，面试可能追问口径。项目顺序按岗位相关度排列，证书与技能放显眼位置。投递后记录公司、岗位、时间与反馈，便于复盘。']
    ],
    ['面试', '本章解决专业题与行为题的应答，重点是用结构化表达展示真实能力与思考过程。',
      ['专业题常考分录、报表勾稽、准则变化、税务处理与财务分析。', '行为题用STAR结构，突出个人行动与结果，避免把团队成果全归个人。', '案例题先澄清目标与约束，再拆解框架，最后给出结论与风险。', '反问环节展示思考，可问团队分工、培养路径与业务挑战。', '面试前研究公司业务、财报与行业，准备两到三个针对性问题。', '回答控制在一到两分钟，先结论后依据，遇到不会的问题诚实说明。'],
      '准备三个覆盖专业、协作与抗压的STAR案例，练习一分钟与三分钟两个版本，面试后记录问题与改进点。',
      '常见错误是夸大经历、答非所问、反问环节说没有问题。纠正方法是只写真实经历并准备追问细节，回答先复述问题，反问准备与岗位相关的问题。',
      ['专业题可举例。面试官问预收款何时确认收入，应回答按新收入准则在控制权转移时确认，预收时计入合同负债，不能以收款或开票为确认时点；再举交付验收的例子说明。若被追问合同负债与预收账款区别，可说明合同负债对应已收对价但尚未履约的合同义务，预收账款更多用于非合同场景。', '行为题要用细节支撑。问讲一次处理冲突的经历，可按情境、任务、行动、结果回答：项目中财务与业务对费用归属有分歧，你整理准则依据与数据，组织会议逐项核对，最终形成统一口径并按时出表。结果尽量量化，如提前两天完成。面试官可能追问你个人的具体贡献，要能说清。']
    ]
  ]
});
